// Üretilen dosya: tool/ozgun/uret.py. Yabancı Dil · Dünya alfabeleri, yazı sistemleri tarihi, etimoloji ve çeviri bilimi (Fenike, Kiril, Göktürk, Uygur, Hangıl, hiyeroglif, yalancı eşdeğerler, ödünçleme) (orta).
const ozLanguage18Orta = <(String, String, List<String>, String)>[
  ('Bir dildeki tek bir sözcüğü veya biçimbirimi (morfemi) bütünüyle temsil eden yazı karakterlerine dilbilimde ne ad verilir?', 'Logogram', ['Sillabogram', 'Allograf', 'Digraf'], 'Logogramlar, salt kavramı değil belirli bir dildeki somut sözcüğü veya biçimbirimi karşılayan karakterlerdir.'),
  ('Piktogram ile logogram arasındaki temel dilbilimsel fark aşağıdakilerden hangisidir?', 'Logogramın dildeki belirli bir sözcüğü karşılaması, piktogramın ise dilden bağımsız nesneyi resmetmesi', ['Piktogramın yalnızca ünlü sesleri, logogramın ise yalnızca ünsüz sesleri göstermesi', 'Logogramın kil tabletlere, piktogramın ise yalnızca papirüs rulolarına yazılabilmesi', 'Piktogramın sağdan sola doğru, logogramın ise yukarıdan aşağıya doğru dizilmesi'], 'Piktogram görsel bir resim iken logogram belirli bir dilin sözvarlığındaki sözcüğe sabitlenmiş yazı birimidir.'),
  ('Yazı tarihinde "rebus ilkesi" (bilmece ilkesi) neyi ifade eder?', 'Resimsel bir işaretin nesne anlamından sıyrılarak yalnızca ses değeri için kullanılmasını', ['Ünlü harflerin ünsüz harflerin üstüne veya altına küçük noktalar halinde eklenmesini', 'Satırların bir soldan sağa, bir sağdan sola doğru öküz sabanı düzeninde yazılmasını', 'Yabancı dillerden alınan ödünç kelimelerin ayrı bir köşeli hece yazısıyla gösterilmesini'], 'Rebus ilkesi, somut bir nesnenin resmini eşsesli soyut kelimeleri veya heceleri yazmak için sesli olarak kullanma aşamasıdır.'),
  ('Yalnızca ünsüz seslerin temel harflerle yazıldığı, ünlü seslerin ise okuyucu tarafından çıkarıldığı veya isteğe bağlı işaretlerle gösterildiği yazı sistemine ne denir?', 'Ebced', ['Abugida', 'Logografi', 'Sillabari'], 'Dilbilimde "abjad" (ebced) adı verilen sistemde temel harfler yalnızca ünsüzleri temsil eder; Arap ve İbrani yazıları bu gruptadır.'),
  ('Antik Mısır hiyeroglif yazısının yapısal niteliği hakkında aşağıdakilerden hangisi doğrudur?', 'Logografik, fonetik (ünsüz) ve belirleyici (determinatif) işaretleri bir arada barındıran karma bir sistemdir', ['Yalnızca soyut kavramları anlatan ve hiçbir ses değeri taşımayan saf bir ideogram dizisidir', 'Her bir sesli ve sessiz harfi ayrı bir kuş figürüyle karşılayan tam fonemik bir alfabedir', 'Babil çivi yazısından türetilmiş olup yalnızca açık heceleri gösteren bir hece yazısıdır'], 'Mısır hiyeroglifleri sanılanın aksine saf resim yazısı olmayıp ünsüz ses işaretleri, logogramlar ve anlam belirleyicilerden oluşur.'),
  ('Sina Yarımadası\'nda bulunan ve Mısır hiyerogliflerinden Fenike yazısına geçiş halkasını oluşturan en eski ünsüz yazısı hangisidir?', 'Proto-Sinaitik yazı', ['Girit Linear A yazısı', 'Ugarit çivi yazısı', 'Etrüsk alfabesi'], 'MÖ 2. binyıl ortalarına tarihlenen Proto-Sinaitik (Ön Sina) yazıtları, hiyeroglif şekillerini Sami dilindeki ilk seslere göre kullanan en eski alfabetik/ebced atasını temsil eder.'),
  ('Fenike alfabesinde toplam kaç temel harf bulunmaktaydı ve bunların ses niteliği neydi?', 'Tamamı ünsüz olan 22 harf', ['17 ünsüz ve 5 ünlüden oluşan 22 harf', 'Tamamı açık hece olan 28 harf', '20 ünsüz ve 6 ünlüden oluşan 26 harf'], 'Standart Fenike yazısı ünlü harf içermeyen 22 ünsüz harften oluşan bir ebced (abjad) sistemidir.'),
  ('"Alfabe" kelimesinin kökeni hangi iki antik Sami/Fenike harf adının birleşimine dayanır?', 'Öküz anlamındaki Alef ve ev anlamındaki Bet', ['Su anlamındaki Mem ve balık anlamındaki Nun', 'El anlamındaki Yod ve baş anlamındaki Reş', 'Göz anlamındaki Ayin ve ağız anlamındaki Pe'], 'Yunanlıların Alpha ve Beta olarak ödünç aldığı bu iki harf, Batı Sami dillerinde öküz (\'alef) ve ev (bet) anlamlarına gelmektedir.'),
  ('Erken dönem Yunan yazıtlarında görülen "boustrophedon" yazım yönü aşağıdakilerden hangisini tanımlar?', 'Satırların dönüşümlü olarak bir sağdan sola, bir soldan sağa doğru devam etmesini', ['Kelimelerin arasına boşluk bırakılmadan tüm metnin bitişik olarak dizilmesini', 'Harflerin sayfanın sağ üst köşesinden başlayarak dikey sütunlar halinde inmesini', 'Sadece büyük harflerin kullanılıp küçük harflere metin içinde hiç yer verilmemesini'], 'Yunanca "öküz dönüşü" anlamına gelen boustrophedon, tarlayı süren saban gibi satır sonunda yön değiştirerek yazma biçimidir.'),
  ('Latin alfabesi, Yunan alfabesinin Batı kolundan İtalya Yarımadası\'ndaki hangi uygarlığın aracılığıyla türemiştir?', 'Etrüskler', ['Kartacalılar', 'Keltler', 'Gotlar'], 'Güney İtalya\'daki Batı Yunan (Cumae/Euboia) alfabesini benimseyen Etrüskler, bu yazıyı Romalılara aktaran kültürel köprü olmuştur.'),
  ('Orta Çağ\'a kadar tek tip büyük harflerden (majüskül) oluşan Latin alfabesinde bugünkü küçük harflerin (minüskül) doğrudan temelini atan yazı üslubu hangisidir?', 'Karolenj minüskülü', ['Roma kapitals yazısı', 'Etrüsk duvar yazısı', 'Runik Futhark yazısı'], 'Şarlman (Charlemagne) döneminde Alcuin öncülüğünde standartlaştırılan Karolenj minüskülü, okunaklı küçük harflerin ve kelime arası boşlukların yaygınlaşmasını sağlamıştır.'),
  ('Klasik Antik Çağ\'da Romalıların kullandığı 23 harflik Latin alfabesine Orta Çağ ve Rönesans dönemlerinde eklenerek harf sayısını 26\'ya çıkaran üç harf hangileridir?', 'J, U ve W', ['K, Y ve Z', 'G, Q ve X', 'C, H ve V'], 'Klasik Latincede I hem \'i\' hem \'j\'yi, V ise hem \'u\' hem \'v\'yi karşılıyordu; J, U ve çift V\'den doğan W sonradan ayrı harfler olarak ayrışmıştır.'),
  ('Kiril alfabesinin tasarımında Yunan alfabesinde karşılığı bulunmayan Slavca sürtünmeli ve ıslıklı sesler (örneğin Ş ve Ç) için ağırlıklı olarak hangi kaynaklardan yararlanılmıştır?', 'Glagol ile İbrani harflerinden uyarlanan ek sembollerden', ['Çin logogramlarının basitleştirilmiş fırça darbelerinden', 'Mısır demotik yazısındaki ticari kısaltma işaretlerinden', 'Arap yazısındaki hareke ve tenvin işaretlerinden'], 'Kiril alfabesinin çekirdeği Bizans Yunan yazısı olmakla birlikte, Ş (Ш) gibi Slavcaya özgü seslerde İbrani Şin (ש) ve Glagol geleneklerinden yararlanılmıştır.'),
  ('Rus Kiril alfabesini modernleştirerek Batı Avrupa matbaa harflerine yaklaştıran "Grajdanskiy şrift" (Sivil Yazı) reformunu 1708\'de hangi hükümdar gerçekleştirmiştir?', 'Büyük Petro', ['Korkunç İvan', 'II. Katerina', 'I. Aleksandr'], 'Çar I. Petro (Büyük Petro), kilise yazısı üslubunu sadeleştirip Latin tipografisine yaklaştıran sivil yazı reformunu yürürlüğe koymuştur.'),
  ('Arap yazısı, Kuzey Arabistan ve Ürdün çevresinde hüküm süren hangi antik ticaret krallığının Arami kökenli yazısından doğrudan evrilmiştir?', 'Nebatiler', ['Sabalar', 'Hititler', 'Lidyalılar'], 'Arap yazısı, Petra merkezli Nebati Krallığı\'nın işlek (kursif) Arami yazısından MS 4-6. yüzyıllar arasında gelişmiştir.'),
  ('Arap ve İbrani gibi ebced yazılarında, aslında ünsüz olan Elif, Vav ve Ye (İbranicede Alef, Vav, Yod) harflerinin uzun ünlüleri göstermek amacıyla kullanılmasına dilbilimde ne ad verilir?', 'Matres lectionis (okuma anaları)', ['Boustrophedon (öküz dönüşü)', 'Scriptio continua (kesintisiz yazı)', 'Virama (ünsüz susturucu)'], 'Latince "okuma anaları" anlamına gelen matres lectionis, Sami ebcedlerinde yanlış okumayı önlemek için bazı ünsüz harflerin uzun ünlüleri işaret etmesidir.'),
  ('Arap yazısında kısa ünlüleri (/a/, /i/, /u/) göstermek üzere harflerin üstüne veya altına konulan fetha, kesra ve damme gibi yardımcı işaretlere ne ad verilir?', 'Hareke', ['İcazet', 'Keşide', 'Mühmel'], 'Harekeler (teşkil), ünsüz iskeletin doğru seslendirilmesini sağlayan yardımcı ünlü işaretleridir ve özellikle Kur\'an-ı Kerim ile dil öğretiminde kullanılır.'),
  ('Modern İbranice ve Yidiş metinlerinde kullanılan "kare yazı" (Ktav Aşuri) tarihsel olarak hangi yazıdan alınmıştır?', 'İmparatorluk Arami yazısından', ['Güney Arabistan Müsned yazısından', 'Yunan unsiyal yazısından', 'Kıpti kilise yazısından'], 'Babil Sürgünü sonrasında Yahudiler eski Paleo-İbrani (Fenike tipi) yazı yerine İmparatorluk Arami yazısından türeyen kare İbrani harflerini benimsemiştir.'),
  ('İbrani alfabesinde toplam kaç temel ünsüz harf bulunur ve kelime sonunda biçim değiştiren (sofit) kaç harf vardır?', '22 temel harf ve 5 sonda biçimi', ['28 temel harf ve 6 sonda biçimi', '24 temel harf ve 2 sonda biçimi', '30 temel harf ve 8 sonda biçimi'], 'İbrani ebcedi 22 ünsüz harften oluşur; Kaf, Mem, Nun, Pe ve Tsadi harfleri (Kaf-Mem-Nun-Pe-Tsadi / KaMNaFeTs) kelime sonunda özel birer "sofit" şekli alır.'),
  ('Kafkasya\'da MS 405 yılı civarında rahip Mesrop Maştots tarafından Hristiyanlık metinlerini yerel dile çevirmek üzere icat edilen tam alfabe hangisidir?', 'Ermeni alfabesi', ['Arami ebcedi', 'Uygur yazısı', 'Pehlevi yazısı'], 'Mesrop Maştots, Ermenicenin zengin ünsüz yapısını eksiksiz karşılayan 36 harflik (sonradan 38/39 olan) özgün bir tam alfabe geliştirmiştir.'),
  ('Kuzey Avrupa\'da Cermen halklarının Hristiyanlık ve Latin alfabesi öncesinde taş, ahşap ve metal üzerine kazıyarak kullandıkları köşeli yazı sistemine ne ad verilir?', 'Runik yazı', ['Ogham çentik yazısı', 'Linear B hece yazısı', 'Glagol kilise yazısı'], 'İlk altı harfinin ses değerlerinden dolayı "Futhark" olarak da anılan Runik alfabe, ahşap liflerine kolay kazınması için yatay çizgilerden kaçınan dik/eğik çizgilerden oluşur.'),
  ('Mısır\'da Hristiyanlık döneminde hiyeroglif geleneğinin son halkası olarak Yunan alfabesine Demotik yazıdan 7 harf eklenmesiyle oluşturulan alfabe hangisidir?', 'Kıpti alfabesi', ['Nebati alfabesi', 'Süryani alfabesi', 'Habeş abugidası'], 'Kıpti alfabesi, 24 Yunan harfine Yunancada bulunmayan Mısır seslerini karşılamak üzere Demotik yazıdan alınan 7 ek harfin katılmasıyla oluşmuş tam bir alfabedir.'),
  ('Orhun Yazıtları\'nda kullanılan Göktürk yazısının satır yönü ve yapısal özelliği hakkında aşağıdakilerden hangisi doğrudur?', 'Genellikle sağdan sola doğru yazılan, ünsüzlerde kalınlık-incelik (ünlü uyumu) ayrımı gözeten 38 işaretlik bir yazıdır', ['Soldan sağa doğru bitişik harflerle yazılan ve yalnızca 22 Sami ünsüzünden oluşan saf bir ebceddir', 'Her kelime için ayrı bir hayvan resmi kullanılan, ses değeri taşımayan piktografik bir kaya yazısıdır', 'Yalnızca açık heceleri gösteren ve Hindistan\'daki Devanagari yazısından doğrudan alınan bir abugidadır'], 'Göktürk alfabesinde dört ünlü harf yanında bazıları kalın, bazıları ince ünlülü kelimelerle kullanılan çiftli ünsüz işaretleri ve çift sesli semboller yer alır.'),
  ('Aşağıdaki dil ve yazı sistemi eşleştirmelerinden hangisinde kullanılan yazı sistemi "ebced" (abjad) kategorisinde yer alır?', 'Arapça ve İbranice', ['Yunanca ve Rusça', 'Japonca (Hiragana) ve Çerokice', 'Hintçe (Devanagari) ve Amharca'], 'Arapça ve İbranice ünsüz harfleri esas alan ebced sistemlerini kullanırken; Yunanca/Rusça tam alfabe, Hiragana/Çerokice hece yazısı, Devanagari/Amharca ise abugida kullanır.'),
  ('Bir dilbilimci incelediği antik bir yazıtta toplam 450 farklı sembol tespit etmişse, bu yazı sisteminin tipolojik olarak aşağıdakilerden hangisi olması en güçlü olasılıktır?', 'Logogram ve hece işaretlerini birleştiren logo-sillabik bir yazı', ['Yalnızca tekil sesbirimleri gösteren saf bir fonemik alfabe', 'Yalnızca ünsüz sesleri kayıt altına alan sade bir ebced', 'Sadece on rakamdan oluşan matematiksel bir sayı sistemi'], 'Alfabeler ve ebcedler genellikle 20-40 arası işarete, saf hece yazıları 50-100 işarete sahipken; birkaç yüz işaretlik envanterler Sümer akadcasi veya Maya gibi logo-sillabik sistemlere işaret eder.'),
  ('Ege dünyasında Girit ve Yunan anakarasında MÖ 2. binyılda kullanılan ve 1952\'de Michael Ventris tarafından Miken Yunancası olduğu çözülen hece yazısı hangisidir?', 'Linear B yazısı', ['Linear A yazısı', 'Phaistos Diski yazısı', 'Frig alfabesi'], 'Mimar ve amatör dilbilimci Michael Ventris, Linear B tabletlerinin Erken (Miken) Yunancasını kaydeden bir hece yazısı olduğunu kanıtlamıştır; Minos uygarlığına ait Linear A ise hâlâ tam çözülememiştir.'),
  ('Orta Amerika\'da (Mezoamerika) Avrupalıların gelişinden önce en gelişmiş logo-sillabik (hem sözcük hem hece işaretli) yazı sistemini kuran uygarlık hangisidir?', 'Mayalar', ['İnkalar', 'Aztekler', 'Olmekler'], 'Klasik Maya uygarlığı, sanatsal bloklar halinde düzenlenen logogramlar ve açık hece işaretleriyle her türlü cümleyi tam olarak yazabilen gelişmiş bir sistem kurmuştur (İnkalar yazı yerine düğümlü ipler olan Quipu kullanmıştır).'),
  ('Etiyopya ve Eritre\'de konuşulan Amharca ve Tigrinya gibi Sami dillerinin yazımında kullanılan Ge\'ez (Habeş) yazısı tipolojik olarak hangi gruba girer?', 'Abugida', ['Saf ebced', 'Logogram', 'Piktogram'], 'Sami dillerinin neredeyse tamamı ebced kullanırken, Güney Arabistan ünsüz yazısından doğan Ge\'ez (Habeş) yazısı MS 4. yüzyılda ünlüler için harf gövdelerine ekler katarak bir abugidaya dönüşmüştür.'),
  ('Kuzey Afrika\'nın yerli halkı olan Berberilerin (Amazigh) antik Libiko-Berber yazısından günümüze ulaşan geometrik karakterli alfabesine ne ad verilir?', 'Tifinag', ['Estrangelo', 'Kharosthi', 'Avesta'], 'Tifinag, Tuaregler aracılığıyla korunan ve Fas ile Cezayir\'de yeniden standartlaştırılan köklü Berberi yazısıdır (geleneksel hali ebced, modern Neo-Tifinag hali tam alfabedir).'),
  ('Kafkasya\'nın özgün alfabelerinden biri olan ve büyük-küçük harf ayrımı (unikameral yapı) bulunmayan yuvarlak hatlı modern Gürcü yazısına ne ad verilir?', 'Mhedruli', ['Asomtavruli', 'Nushuri', 'Glagolitsa'], 'Gürcü yazı tarihinin üç aşamasından (Asomtavruli, Nushuri, Mhedruli) sivil/şövalye yazısı olan Mhedruli, büyük-küçük harf ayrımı içermeyen 33 harflik tam fonemik bir alfabedir.'),
  ('Kuzey Amerika\'da 1820\'li yıllarda tek başına okuma yazma bilmemesine rağmen kendi halkının dili için 85 işaretlik kusursuz bir hece yazısı icat eden Çeroki yerlisi kimdir?', 'Sequoyah', ['Tecumseh', 'Geronimo', 'Sitting Bull'], 'Sequoyah, İngilizce metinlerdeki Latin harflerinin şekillerinden esinlense de onlara bambaşka hece değerleri vererek Çerokice için kısa sürede tüm ulusunu okuryazar yapan bir hece yazısı (sillabary) tasarlamıştır.'),
  ('İslam dünyasında el yazması kitapların çoğaltılmasında okunaklılığı nedeniyle en yaygın standart metin yazısı haline gelen ve matbaa harflerine de temel oluşturan hat türü hangisidir?', 'Nesih', ['Sülüs', 'Tuğra', 'Siyakat'], 'İbn Mukle ve İbnü\'l-Bevvâb tarafından oranları mükemmelleştirilen Nesih hattı ("kopyalama/istinsah yazısı"), yüksek okunaklılığı sayesinde kitap ve Kur\'an yazımının ana standardı olmuştur.'),
  ('Süryani Hristiyan edebiyatında kullanılan Estrangelo, Serto ve Madnhaya (Doğu/Nasturi) yazı üslupları tipolojik olarak hangi gruba aittir?', 'Sağdan sola bitişik yazılan 22 harflik Arami kökenli ebced sistemine', ['Soldan sağa ayrı harflerle yazılan Yunan kökenli tam alfabe sistemine', 'Ünsüz tabanlarına zorunlu ünlü halkaları eklenen Hint kökenli abugida sistemine', 'Yukarıdan aşağıya fırçayla çizilen Çin kökenli logografik sisteme'], 'Süryani yazısının tüm tarihsel üslupları (klasik Estrangelo, Batı Serto, Doğu Madnhaya) Arami kolundan doğmuş 22 ünsüzlü ve sağdan sola bitişik yazılan ebcedlerdir.'),
  ('İngilizce "knight" (/naɪt/) veya Fransızca "eaux" (/o/) kelimelerinde olduğu gibi harfler ile güncel telaffuz arasındaki mesafenin açıldığı yazı düzenlerine dilbilimde ne denir?', 'Derin (etimolojik/tarihsel) imla', ['Sığ (fonemik/şeffaf) imla', 'Piktografik (resimsel) imla', 'Boustrophedon (dönüşümlü) imla'], 'Dilin konuşma sesleri yüzyıllar içinde değişirken yazılışın eski tarihsel biçimi koruması "derin ortografi" (deep orthography) yaratır; Türkçe, Fince ve İspanyolca ise "sığ/şeffaf ortografi" örnekleridir.'),
  ('Gotça İncil çevirisini yapmak amacıyla 4. yüzyılda Piskopos Wulfila (Ulfilas) tarafından Yunan, Latin ve Runik unsurlar harmanlanarak oluşturulan alfabe hangisidir?', 'Got alfabesi', ['Glagol alfabesi', 'Ermeni alfabesi', 'Arnavut Elbasan alfabesi'], 'Piskopos Wulfila, Doğu Cermen dili olan Gotçayı yazıya geçirmek için esas olarak Yunan unsiyal yazısına dayanan, yer yer Latin ve Runik işaretlerden yararlanan Got alfabesini icat etmiştir.'),
  ('Arap alfabesinde kendisinden önce gelen harfe bitişebilen ancak kendisinden sonra gelen hiçbir harfe sol taraftan bitişmeyen altı harf hangileridir?', 'Elif, Dal, Zel, Ra, Ze ve Vav', ['Be, Te, Se, Cim, Ha ve Hı', 'Sin, Şın, Sad, Dad, Tı ve Zı', 'Fâ, Kaf, Kef, Lam, Mim ve Nun'], 'Arap yazısında ا، د، ذ، ر، ز، و (Elif, Dal, Zel, Ra, Ze, Vav) harfleri sollarındaki harfe bağlanmaz; bu kural kelimelerin görsel bütünlüğünü ve okunaklılığını korur.'),
  ('Antik Kuzeybatı Hindistan ve Gandhara bölgesinde (bugünkü Pakistan ve Afganistan) kullanılan, Brahmi\'nin aksine sağdan sola doğru yazılan ve zamanla soyu tükenen Arami kökenli yazı hangisidir?', 'Kharosthi yazısı', ['Gurmukhi yazısı', 'Sinhala yazısı', 'Telugu yazısı'], 'Kharosthi yazısı Arami ebcedinden doğrudan türemiş sağdan sola yazılan bir abugidaydı; ancak Güney Asya\'da soldan sağa yazılan Brahmi kolu kalıcı üstünlük sağladı.'),
  ('Devanagari gibi Hint abugida sistemlerinde tek başına yazılan her ünsüz harfin (örneğin क) varsayılan olarak bünyesinde barındırdığı doğal ünlü (inherent vowel) hangisidir?', 'Kısa /a/ (veya şva /ə/) ünlüsü', ['Uzun /u:/ ünlüsü', 'İnce /i/ ünlüsü', 'Yuvarlak /o/ ünlüsü'], 'Abugida sistemlerinde ek bir işaret almayan her temel ünsüz harf otomatik olarak kısa \'a\' ünlüsüyle (ka, ga, ma şeklinde) okunur.'),
  ('Devanagari\'de kelime boyunca harflerin üst tavanını birbirine bağlayan yatay çizgiye Sanskritçe tipografi terimiyle ne ad verilir?', 'Şirorekha', ['Matra', 'Akşara', 'Bindu'], '"Baş çizgisi" anlamına gelen Şirorekha, Devanagari ve Bengal yazılarında aynı kelimeye ait hece birimlerini üstten tek bir çatı altında birleştirir.'),
  ('Devanagari yazısında varsayılan /a/ dışındaki ünlüleri (/i/, /u/, /e/, /o/ vb.) göstermek üzere ünsüz gövdesinin sağına, soluna, altına veya üstüne eklenen bağımlı ünlü işaretlerine ne denir?', 'Matra', ['Radikal', 'Furigana', 'Nikud'], 'Ünlü harfler kelime başında bağımsız şekilleriyle yazılırken, bir ünsüzden sonra geldiklerinde "matra" adı verilen bağımlı ek işaretlere dönüşürler.'),
  ('Geleneksel Sanskrit ve Devanagari harf tablosunun (Varnamala) diziliş sırası Batı alfabelerinden farklı olarak hangi ölçüte göre düzenlenmiştir?', 'Seslerin ağız içindeki boğumlanma (çıkış) noktalarına ve sesbilimsel özelliklerine göre', ['Harflerin tarih boyunca icat edildikleri yüzyılların kronolojik sırasına göre', 'Harfleri çizmek için gereken fırça veya kalem darbelerinin azdan çoğa sayısına göre', 'Harf adlarının temsil ettiği hayvan ve bitki türlerinin büyüklük sırasına göre'], 'Panini dilbilgisi geleneğini yansıtan Hint yazı tabloları rastgele değil; önce ünlüler, ardından gırtlaktan dudaklara doğru çıkış yerlerine ve solukluluk/ötümlülük durumuna göre bilimsel bir fonetik sırayla dizilir.'),
  ('Güney Hindistan\'da (Tamil, Malayalam, Kannada, Telugu) ve Sri Lanka\'da (Sinhala) kullanılan yazıların Kuzey Hindistan\'daki köşeli Devanagari\'nin aksine çok kıvrımlı ve yuvarlak hatlara sahip olmasının tarihsel nedeni nedir?', 'Kurutulmuş palmiye yaprakları üzerine metal kalemle kazınırken düz yatay çizgilerin yaprağı lifleri boyunca yırtma tehlikesi', ['Güney Hindistan halklarının harfleri sadece deniz kumları üzerine dairesel deniz kabukları bastırarak yazması', 'Bu yazıların Brahmi yerine doğrudan yuvarlak hatlı Gürcü Mhedruli alfabesinden kopyalanmış olması', 'Portekizli denizcilerin 16. yüzyılda bölgedeki tüm köşeli harfleri yasaklayarak el yazısı dayatması'], 'Palmiye yaprağı (ola) üzerine sivri demir uçla düz çizgiler çekmek yaprağı boydan boya yardığı için Güney Hindistan ve Güneydoğu Asya katipleri dairesel kıvrımlı harf formları geliştirmiştir.'),
  ('Tibetçe ve Dzongkha (Bhutan) dillerinin yazımında kullanılan Tibet yazısı, MS 7. yüzyılda hangi yazı ailesinden türetilmiştir?', 'Kuzey Hindistan\'daki Gupta/Brahmi abugida ailesinden', ['Kuzey Çin\'deki Şang Hanedanı fal yazıtları sisteminden', 'Orta Asya\'daki Göktürk runik kaya yazısı sisteminden', 'İran\'daki Sasani Pehlevi ebced yazısı sisteminden'], 'Tibet Kralı Songtsen Gampo\'nun bakanı Thönmi Sambhota, Budist metinleri çevirmek üzere Hindistan\'daki Gupta dönemi Brahmi yazısını esas alarak Tibet abugidasını oluşturmuştur.'),
  ('Çin\'i MÖ 221\'de ilk kez tek bayrak altında birleştiren İmparator Çin Şi Huang ve veziri Li Si\'nin ülkedeki bölgesel yazı farklılıklarını ortadan kaldırarak standartlaştırdığı yazı üslubu hangisidir?', 'Küçük Mühür Yazısı (Xiaozhuan)', ['Fal Kemiği Yazısı (Jiaguwen)', 'Çim/İşlek El Yazısı (Caoshu)', 'Basitleştirilmiş Modern Yazı (Jiantizi)'], 'Çin Şi Huang döneminde "yazının birleştirilmesi" (şutongwen) politikasıyla Küçük Mühür Yazısı resmi standart yapılarak farklı lehçeler arasında ortak yazılı iletişim sağlanmıştır.'),
  ('Çin karakterlerinin (Hanzi) yaklaşık %80\'inden fazlasını oluşturan "fono-semantik bileşikler" (Xingsheng) yapısal olarak hangi iki unsurun birleşimidir?', 'Anlam kategorisini sezdiren bir kök (radikal) ile yaklaşık okunuşu veren bir ses bileşeni', ['Yalnızca soyut felsefi kavramları gösteren iki adet dilsiz resim sembolü', 'Kelimenin baş ünsüzünü veren bir Latin harfi ile tonunu gösteren bir rakam', 'Cümlenin öznesini gösteren bir zamir ile zamanını gösteren bir fiil çekim eki'], 'Yaygın kanının aksine Çin karakterlerinin büyük çoğunluğu saf resim değil; biri anlam kümesini (su, ağaç, kalp vb.), diğeri yaklaşık sesi işaret eden iki parçalı bileşik logogramlardır.'),
  ('Çin sözlüklerinde karakterleri bulmayı kolaylaştıran ve "su (氵), insan (亻), ağaç (木), el (扌)" gibi temel anlam/biçim gruplarını temsil eden kurucu parçalara ne ad verilir?', 'Radikal', ['Digraf', 'Virama', 'Hareke'], '1716 tarihli Kangşi Sözlüğü\'nde 214 adet olarak standartlaştırılan radikaller, binlerce Çin karakterini sınıflandırmaya ve anlam ipucu vermeye yarayan bileşenlerdir.'),
  ('Çin Halk Cumhuriyeti\'nin 1950\'li yıllarda okuryazarlık oranını hızla artırmak amacıyla karakterlerin fırça darbesi (vuruş) sayılarını azaltarak uygulamaya koyduğu yazı reformunun ürünü nedir?', 'Basitleştirilmiş Çince karakterler', ['Geleneksel Mühür karakterleri', 'Katakana köşeli hece işaretleri', 'Bopomofo yarı-hece harfleri'], 'Anakara Çin, Singapur ve Malezya "Basitleştirilmiş Çince" (Jiantizi) karakterleri kullanırken; Tayvan, Hong Kong ve Makao çok vuruşlu "Geleneksel Çince" (Fantizi) karakterleri korumuştur.'),
  ('Tayvan\'da Çince karakterlerin okunuşunu öğretmek ve dijital klavye girişi yapmak için yaygın olarak kullanılan, Latin harfli olmayan 37 işaretlik ulusal fonetik sisteme ne ad verilir?', 'Juyin Fuhao', ['Hiragana', 'Hangıl', 'Tifinag'], 'İlk dört işaretinin okunuşundan dolayı "Bopomofo" olarak bilinen Juyin Fuhao, 1910\'larda eski Çin karakter parçalarından türetilmiş yarı-hecesel bir ses gösterim sistemidir.'),
  ('Japoncada yuvarlak ve akıcı hatlara sahip olan "Hiragana" hece yazısının cümle içindeki birincil dilbilgisel görevi nedir?', 'Fiil ve sıfat çekim eklerini (okurigana), edatları ve Kanji karşılığı olmayan yerli Japonca kelimeleri yazmak', ['İngilizce, Fransızca ve Almanca gibi Batı dillerinden yeni giren teknolojik terimleri yazmak', 'Sadece imparatorluk sarayındaki resmi mühürleri ve tapınak kapılarındaki Çince beyitleri yazmak', 'Yabancı turistler için tren istasyonu tabelalarını Latin harflerine çevirerek göstermek'], 'Japonca sondan eklemeli bir dil olduğundan Çinceden alınan sabit Kanji köklerinin sonuna gelen tüm çekim ekleri ve cümle edatları Hiragana ile yazılır.'),
  ('Japoncada keskin ve köşeli çizgilere sahip olan "Katakana" hece yazısı ağırlıklı olarak hangi tür kelimelerin yazımında kullanılır?', 'Batı dillerinden geçen yabancı ödünç kelimeler (gairaigo), yabancı özel adlar, yansıma sesler ve bilimsel tür adlarında', ['Geleneksel Japon şiirleri olan haikulardaki fiil çekim eklerinde ve cümle içi bağlaçlarda', 'Budist rahiplerin mezar taşlarına kazıdıkları klasik Çince felsefe metinlerinde', 'İlkokul birinci sınıf öğrencilerinin sadece rakamları ve toplama işlemlerini yazdığı defterlerde'], 'Katakana; "konpyūta" (bilgisayar) veya "terebi" (televizyon) gibi alıntı kelimeleri, yabancı ülke/kişi adlarını, yansıma sözcükleri ve italik benzeri vurguları göstermek için kullanılır.'),
  ('Japon yazı tarihinde Kanji karakterlerinden Hiragana ve Katakana hece yazılarının doğuşuna geçiş köprüsü olan, Çince karakterlerin anlamını bir yana bırakıp sadece sesleri için kullanıldığı erken sisteme ne denir?', 'Manyogana', ['Furigana', 'Okurigana', 'Romaji'], '8. yüzyıldaki "Manyoşu" şiir antolojisinden adını alan Manyogana sistemi, Japonca heceleri Çince karakterlerin sadece ses değerleriyle yazma yöntemiydi.'),
  ('Japoncada nadir veya zor bir Kanji karakterinin nasıl okunacağını göstermek amacıyla karakterin hemen üstüne (dikey yazıda sağına) küçük boyutlu kana harfleriyle düşülen okuma kılavuzuna ne ad verilir?', 'Furigana', ['Okurigana', 'Katakana', 'Dakuten'], 'Çocuk kitaplarında, mangalarda ve az bilinen özel isimlerde Kanji\'nin okunuşunu küçük Hiragana/Katakana harfleriyle üstte gösteren yardımcı sisteme Furigana denir.'),
  ('Japonca Hiragana ve Katakana hece yazılarında "ka (か)" hecesinin sağ üst köşesine iki küçük tırnak işareti olan "dakuten" (゛) eklendiğinde hecenin okunuşu nasıl değişir?', 'Ötümsüz ünsüz ötümlüleşerek "ga (が)" hecesine dönüşür', ['Ünlü düşerek sadece saf ünsüz olan "/k/" sesine dönüşür', 'Hece uzun okunarak "kaa" biçiminde iki vuruşluk ses olur', 'Hecenin başındaki ünsüz silinerek tek başına "/a/" ünlüsü kalır'], 'Dakuten (nigori) işareti ötümsüz ünsüzle başlayan heceleri ötümlü karşılıklarına çevirir (k->g, s->z, t->d, h->b); yuvarlak "handakuten" (゜) ise h dizisini p dizisine (ha->pa) çevirir.'),
  ('Japon Eğitim Bakanlığı tarafından lise sonuna kadar öğretilen ve gazete, dergi, resmi belgelerde standart olarak kullanılan yaklaşık 2.136 temel karakterlik resmi Kanji listesine ne ad verilir?', 'Coyo Kanji', ['Manyogana', 'Gojuon', 'Hanyu Pinyin'], '"Günlük kullanım Kanjileri" anlamına gelen Jōyō Kanji listesi, genel basın-yayın ve kamusal okuryazarlık için temel alınan resmi karakter havuzudur.'),
  ('Kral Sejong\'un yeni Kore alfabesini 1446 yılında halka tanıttığı ve "Halka Doğru Sesleri Öğreten Belge" anlamına gelen tarihi eserin (ve alfabenin ilk adının) ismi nedir?', 'Hunmin Congım', ['Samguk Sagi', 'Tripitaka Koreana', 'Dongıi Bogam'], 'UNESCO Dünya Belleği Kütüğü\'nde yer alan "Hunminjeongeum", hem alfabenin ilk resmi adı hem de tasarım ilkelerini bilimsel olarak açıklayan el kitabıdır ("Hangıl" adı 20. yüzyıl başında Ju Si-gyeong tarafından verilmiştir).'),
  ('Hangıl alfabesindeki temel ünlü harfler (ㆍ, ㅡ, ㅣ) geleneksel Doğu Asya felsefesindeki hangi üç kozmik kavramı simgeleyecek biçimde tasarlanmıştır?', 'Gök (nokta), Yer (yatay çizgi) ve İnsan', ['Ateş, Su ve Rüzgâr', 'Güneş, Ay ve Yıldızlar', 'Geçmiş, Şimdi ve Gelecek'], 'Hunminjeongeum\'a göre Hangıl ünlüleri "Cheon-Ji-İn" (Üç Uyum) felsefesine dayanır: yuvarlak nokta Göğü, düz yatay çizgi (ㅡ) Yeri, dikey çizgi (ㅣ) ise ayakta duran İnsanı temsil eder.'),
  ('Hangıl\'ı oluşturan bireysel ünsüz ve ünlü harf birimlerine Korecede ne ad verilir?', 'Jamo', ['Kanji', 'Matra', 'Runik'], 'Modern Hangıl\'da 14 temel ünsüz ve 10 temel ünlü olmak üzere 24 temel "jamo" (harf birimi) bulunur; bunlar bloklar içinde birleşerek binlerce heceyi oluşturur.'),
  ('Kore\'de Kral Sejong\'un 15. yüzyılda Hangıl\'ı icat etmesine rağmen yüzyıllar boyunca seçkin bürokrat sınıfının (Yangban) resmi yazışmalarda vazgeçmeyip 20. yüzyıla dek sürdürdüğü Çin karakterlerine Korecede ne denir?', 'Hanja', ['Katakana', 'Chu Nom', 'Pinyin'], 'Çin karakterleri Çincede "Hanzi", Japoncada "Kanji", Korecede ise "Hanja" olarak adlandırılır; bilgin bürokratlar Hangıl\'ı fazla kolay bularak uzun süre küçümsemiştir.'),
  ('Aşağıdaki yazı sistemlerinden hangileri tipolojik olarak birbirleriyle doğru eşleştirilmiştir?', 'Fenike: Ebced — Devanagari: Abugida — Hiragana: Hece yazısı — Hangıl: Özelliksel alfabe', ['Fenike: Tam alfabe — Devanagari: Logogram — Hiragana: Ebced — Hangıl: Piktogram', 'Fenike: Hece yazısı — Devanagari: Tam alfabe — Hiragana: Abugida — Hangıl: Logogram', 'Fenike: Abugida — Devanagari: Ebced — Hiragana: Özelliksel alfabe — Hangıl: Hece yazısı'], 'Dünya yazı tipolojisinin dört klasik temsilcisinden Fenike yalnızca ünsüzlü ebced, Devanagari ünlü-tabanlı abugida, Hiragana saf hece yazısı, Hangıl ise bloklar halinde yazılan özelliksel (featural) alfabedir.'),
  ('Maldivler\'de konuşulan Hint-Ari dili Dhivehi\'nin yazımında kullanılan ve rakamlardan türetilmiş harfleriyle sağdan sola doğru yazılan "Thaana" yazısının ilginç yapısal özelliği nedir?', 'İlk dokuz harfinin Arap rakamlarından, sonraki dokuz harfinin yerel rakamlardan alınıp zorunlu ünlü harekeleriyle tam bir abugida/alfabe hibriti oluşturması', ['Harflerinin tamamının Hint Okyanusu\'ndaki mercan ve balık türlerinin piktografik çizimlerinden oluşması', 'Dünyada aşağıdan yukarıya doğru yazılan ve tersten okunan tek ada yazısı olması', 'Hiçbir ünsüz harf barındırmayıp yalnızca sekiz adet uzun ünlü harften meydana gelmesi'], '16-18. yüzyıllarda ortaya çıkan Thaana yazısı, Arap (١٢٣...) ve yerel Hint rakamlarını ünsüz tabanı olarak kullanıp Arap harekelerini zorunlu ünlü işaretlerine dönüştüren benzersiz bir sistemdir.'),
  ('Kanada\'daki İnuit (Eskimo) ve Kri (Cree) yerli halklarının kullandığı, temel bir geometrik şeklin (örneğin üçgen veya açının) 90 derecelik açılarla döndürülmesiyle ünlünün değiştiği yazı sistemine ne ad verilir?', 'Kanada Yerli Hece Yazısı', ['Çeroki Hece Yazısı', 'Maya Hiyeroglif Sistemi', 'Runik Futhark Yazısı'], '1840\'ta misyoner James Evans tarafından Kri dili için geliştirilip İnuitlerce benimsenen bu abugida/hece sisteminde sembolün şekli ünsüzü, baktığı yön (yukarı, aşağı, sağa, sola döndürülmesi) ise ünlü sesi belirler (örneğin ᐃ = i, ᐅ = u, ᐊ = a).'),
  ('Braille kabartma yazı sistemi dilbilimsel açıdan bağımsız bir dil midir, yoksa nasıl bir işlev görür?', 'Bağımsız bir dil olmayıp Türkçe, İngilizce, Arapça, Çince gibi farklı dillerin alfabe ve ses sistemlerini dokunsal olarak kodlayan bir yazı uyarlamasıdır', ['Dünyadaki bütün görme engellilerin ana dillerini bırakarak konuştuğu yapay bir uluslararası sözlü dildir', 'Sadece matematik formüllerini ve müzik notalarını göstermek için kullanılan resimsel bir ideogramdır', 'Yalnızca Fransızca kelimeleri harf harf çevirebilen ve başka hiçbir dile uyarlanamayan kapalı bir şifredir'], 'Tıpkı Latin veya Kiril alfabesinin birçok dili yazabilmesi gibi Braille da her dilin kendi harf, hece veya ses (Çincede Pinyin/Juyin) yapısına uyarlanan dokunsal bir yazı kodlamasıdır.'),
  ('Dünyadaki tüm dillerin konuşma seslerini dar ve kesin bir bilimsel standartla göstermek üzere 1888\'de Paul Passy ve meslektaşları tarafından Latin (ve kısmen Yunan) harfleri temelinde geliştirilen sistem hangisidir?', 'Uluslararası Fonetik Alfabe', ['Evrensel Esperanto Alfabesi', 'ASCII Bilgisayar Kodlaması', 'Mors Telgraf Alfabesi'], 'Uluslararası Fonetik Alfabe (IPA), ülkelerin tutarsız imla kurallarından bağımsız olarak insan hançeresinin üretebildiği her konuşma sesini tek ve evrensel bir sembolle gösterir.'),
  ('Paskalya Adası\'nda (Rapa Nui) ahşap tabletler üzerine ters-düz boustrophedon düzeninde kazınan ve anlamı henüz bilimsel uzlaşıyla çözülememiş olan gizemli yazı/işaret sistemi hangisidir?', 'Rongorongo', ['Linear B', 'Ugarit çivi yazısı', 'Meroitik yazı'], 'Güney Pasifik\'teki Paskalya Adası\'nda bulunan "Rongorongo" tabletleri, kuş-insan figürleri ve geometrik şekilleriyle her satırda tableti 180 derece çevirerek okunan çözülememiş bir sistemdir.'),
  ('MÖ 2600-1900 yılları arasında bugünkü Pakistan ve Kuzeybatı Hindistan\'daki Harappa ve Mohenjo-daro kentlerinde mühürler üzerinde görülen, çok kısa yazıtlar içerdiği için hâlâ çözülememiş olan antik sistem hangisidir?', 'İndus Vadisi yazısı', ['Brahmi yazısı', 'Elam çivi yazısı', 'Kharosthi yazısı'], 'Tek boynuzlu hayvan figürlü damga mühürler üzerinde ortalama 4-5 işaretlik diziler halinde bulunan İndus (Harappa) işaretlerinin tam bir dil yazısı mı yoksa hanedan/ticaret arması sistemi mi olduğu hâlâ tartışmalıdır.'),
  ('Anadolu\'da Hitit İmparatorluğu\'nun başkenti Hattuşa arşivlerinde çivi yazısının yanı sıra taş anıtlarda ve kral mühürlerinde kullanılan ikinci yazı sistemi hangisidir?', 'Anadolu (Luvi) hiyeroglifleri', ['Fenike denizci ebcedi', 'Eski Fars çivi yazısı', 'Yunan boustrophedon alfabesi'], 'Hititler kil tabletlerde Mezopotamya\'dan aldıkları çivi yazısını kullanırken, açık hava kaya kabartmalarında ve mühürlerde Luviceyi kaydeden yerli Anadolu hiyerogliflerini (logo-sillabik sistem) kullanmıştır.'),
  ('Sırp-Hırvat dil alanında Sırpçanın yazı sistemi açısından Avrupa\'da nadir görülen "digrafik" (eşzamanlı iki alfabeli) özelliği nedir?', 'Hem Kiril alfabesinin hem de Latin (Gaj) alfabesinin birbirine bire bir harf karşılığı olacak biçimde aktif olarak kullanılması', ['Cümlelerin ilk yarısının Yunan alfabesiyle, ikinci yarısının ise İbrani kare yazısıyla yazılması', 'Resmi belgelerde Çin logogramlarının, günlük mektuplarda ise Arap ebcedinin tercih edilmesi', 'Büyük harflerin tamamının Runik alfabeden, küçük harflerin ise Ermeni alfabesinden seçilmesi'], 'Vuk Karadžić\'in Kiril reformu ile Ljudevit Gaj\'ın Latin reformu tam simetrik kurulduğundan Sırpçada her Kiril harfinin (Љ, Њ, Џ dahil) Latin alfabesinde bire bir karşılığı (Lj, Nj, Dž) vardır.'),
  ('Çekçe (č, š, ž) ve ondan etkilenen Hırvatça, Litvanca gibi Latin alfabeli dillerde tek ses için iki harf (digraf) kullanmak yerine harflerin üstüne konulan küçük ters şapka (ˇ) işaretini 15. yüzyılda yaygınlaştıran reformcu kimdir?', 'Jan Hus', ['Martin Luther', 'Johannes Gutenberg', 'Aziz Kiril'], 'Bohemyalı dini reformcu Jan Hus, "De orthographia bohemica" adlı eserinde "cz, sz" gibi hantal çoklu harfler yerine nokta/çengel (daha sonra háček/karon "ˇ" olan) diyakritik sistemini önererek Slav ve Baltık Latin imlalarını şekillendirmiştir.'),
  ('Moğolistan\'da 20. yüzyılın ortalarından itibaren yaygın olarak kullanılan Kiril alfabesinin yanı sıra kültürel miras kapsamında yeniden canlandırılan geleneksel Moğol yazısının (Hudum Mongol biçiği) ayırt edici görünümü nasıldır?', 'Yukarıdan aşağıya doğru dikey omurga çizgisi boyunca bitişik yazılan ve sütunları soldan sağa dizilen bir yazıdır', ['Sağdan sola doğru birbirinden kopuk kare kutular içinde yazılan çivi benzeri bir yazıdır', 'Aşağıdan yukarıya doğru taş kenarlarına çentikler atılarak oluşturulan noktalı bir yazıdır', 'Üstten kesintisiz bir yatay çizgiyle bağlanan ve soldan sağa yazılan Hint kökenli bir abugidadır'], 'Eski Uygur yazısından türeyen geleneksel Moğol yazısı, dünyada yukarıdan aşağıya dikey yazılıp sütunları (Çin ve Japon dikey yazısının aksine) soldan sağa doğru ilerleyen nadir sistemdir.'),
  ('Bir gezgin Güneydoğu Asya\'da seyahat ederken Vietnam\'a geçtiğinde sokak tabelalarında Çin karakterleri veya Brahmi kökenli kıvrımlı abugidalar yerine yoğun şapka, çengel ve vurgu işaretleri taşıyan Latin harfleri görürse bunun nedeni nedir?', 'Vietnamcanın 20. yüzyıldan beri altı tonu ve zengin ünlülerini diyakritik işaretlerle gösteren Latin tabanlı Quốc Ngữ alfabesini kullanması', ['Vietnam\'ın tarih boyunca Çin kültürüyle hiçbir temas kurmayıp doğrudan Antik Roma İmparatorluğu tarafından kurulmuş olması', 'Vietnam dilinde hiçbir tonlama ve ünlü farkı bulunmadığı için sadece 15 sade Latin harfinin yeterli gelmesi', 'Güneydoğu Asya\'daki Tayland, Kamboçya, Laos ve Myanmar dahil bütün ülkelerin tamamının resmi olarak Latin alfabesine geçmiş olması'], 'Komşuları Tayland, Laos, Kamboçya ve Myanmar Brahmi kökenli abugidalar kullanırken; Vietnam hem Çince (Hán-Nôm) mirasını bırakmış hem de tonlamaları çift katmanlı diyakritiklerle kodlayan Latin alfabesini (Chữ Quốc Ngữ) benimsemiştir.'),
  ('Farsça, Urduca ve Osmanlı Türkçesi edebi metinlerinde şiirsel ve asılı duran eğimli hatlarıyla büyük rağbet gören, İran\'da Mir Ali Tebrizî tarafından 14. yüzyılda sistemleştirilen İslam hat üslubu hangisidir?', 'Nesta\'lik', ['Mağribî', 'Kûfî', 'Siyakat'], 'Nesih ve Ta\'lik hatlarının sentezinden doğan Nesta\'lik (Osmanlıda kısaca Ta\'lik denir), sağdan sola hafifçe alçalan zarif kavisleriyle İran, Babür (Urduca hâlâ bu üslupla dizilir) ve Osmanlı divan edebiyatının gözde yazısı olmuştur.'),
  ('Arap alfabesini Farsça ve Osmanlı Türkçesine uyarlarken Arapçada bulunmayan /p/, /ç/, /j/ ve /g/ seslerini göstermek için hangi yöntem izlenmiştir?', 'Mevcut Arap harflerine (Be, Cim, Ze, Kef) üç nokta veya ek keşide çizgisi eklenerek پ, چ, ژ, گ harfleri türetilmiştir', ['Yunan alfabesindeki Pi, Chi, Zeta ve Gamma harfleri hiçbir değişiklik yapılmadan Arap satırlarının arasına serpiştirilmiştir', 'Bu dört sesi içeren bütün kelimeler dilden tamamen atılarak yerlerine yalnızca gırtlak ünsüzlü kelimeler konulmuştur', 'Söz konusu sesler harfle yazılmayıp yalnızca sayfa kenarına çizilen küçük kuş ve çiçek motifleriyle ima edilmiştir'], 'Farslar Arap ebcedini kendi Hint-Avrupa dillerine uyarlarken sistemin estetik bütünlüğünü bozmadan nokta sayısını artırarak dört yeni harf (Çehâr harf-i Fârisî: پ چ ژ گ) eklemiş, Türkler ve Urdular da bu harfleri devralmıştır.'),
  ('Bir araştırmacı sağdan sola doğru yazılan, harfleri satır tabanında birbirine bitişmeyen, 22 temel ünsüzden oluşan ve kelimenin sonunda 5 harfinin özel kuyruklu/kapalı biçim aldığı bir metin inceliyorsa bu metin hangi alfabeyle yazılmıştır?', 'İbrani alfabesi', ['Arap alfabesi', 'Devanagari yazısı', 'Kiril alfabesi'], 'Sağdan sola yazılması, bitişik olmaması, 22 ünsüz harf barındırması ve 5 sonda biçimi (sofit harfler) içermesi doğrudan kare İbrani yazısını tanımlar.'),
  ('Vilhelm Thomsen, Orhun Yazıtları\'ndaki metinleri çözerken ilk aşamada hangi özel ad ve kavram sözcüklerini anahtar olarak belirlemiştir?', 'Tengri, Türk ve Kül Tigin', ['Kağan, Bilge ve Ötüken', 'Tonyukuk, Bodun ve İlteriş', 'Subaşı, Tigin ve Yollug'], 'Thomsen, metinde sık tekrarlanan Tengri, Türk ve Kül Tigin sözcüklerindeki ses değerlerinden hareketle alfabeyi çözmüştür.'),
  ('Göktürk alfabesinde b, d, g, k, l, n, r, s, t, y ünsüzlerinin her biri için iki ayrı damga bulunmasının temel sesbilimsel nedeni nedir?', 'Kalın ve ince sıradaki ünlülerle hece uyumunu göstermek', ['Sözcük başı ve sözcük sonu konumlarını birbirinden ayırmak', 'Uzun ünlülerle kısa ünlüleri yazıda belirginleştirmek', 'Ödünç sözcüklerle Türkçe kökenli sözcükleri ayırt etmek'], 'Bu on ünsüzün kalın ve ince ünlülü sözcüklerde ayrı damgalarla yazılması büyük ünlü uyumunu yazıya yansıtır.'),
  ('Göktürk alfabesiyle yazılan metinlerde sözcükleri veya sözcük gruplarını birbirinden ayırmak amacıyla hangi işaret kullanılmıştır?', 'Üst üste iki nokta (:)', ['Yatay kısa çizgi (-)', 'Eğik taksim çizgisi (/)', 'Üçgen biçimli tek nokta'], 'Orhun metinlerinde kelimeleri ayırmak için üst üste konulan iki nokta (:) işareti yaygın olarak kullanılmıştır.'),
  ('Orhun Yazıtları\'ndan Kül Tigin ve Bilge Kağan abidelerinin batı yüzlerinde Çince metinlerin de yer alması, Vilhelm Thomsen\'in çözüm sürecine nasıl katkı sağlamıştır?', 'Kişi adlarının ve tarihsel olayların karşılaştırmalı olarak doğrulanmasını sağlamıştır', ['Göktürk damgalarının doğrudan Çin ideogramlarından türediğini kanıtlamıştır', 'Metnin tamamının satır satır birebir sözlük karşılığını hazır olarak sunmuştur', 'Harflerin soldan sağa doğru okunması gerektiğini kesin biçimde göstermiştir'], 'Çince yüzlerdeki Kül Tigin ve Türk gibi özel adlar, Türkçe metindeki ses karşılıklarının tespitini kolaylaştırmıştır.'),
  ('Uygur alfabesi köken bakımından Orta Asya\'da ticaret ve kültür dili olarak kullanılan hangi Sami kökenli alfabeden türemiştir?', 'Soğd alfabesinden', ['Brahmi alfabesinden', 'Grek alfabesinden', 'Tibet alfabesinden'], 'Uygur alfabesi, Aramice üzerinden gelişen İrani Soğd alfabesinin işlek (kursiv) türünden uyarlanmıştır.'),
  ('Uygur alfabesinin Türkçenin ses yapısını göstermede Göktürk alfabesine kıyasla yetersiz kalmasının başlıca nedeni nedir?', 'Birden fazla Türkçe sesin aynı harfle yazılması ve kalınlık-incelik ayrımının sınırlı olması', ['Yalnızca sessiz harflerden oluşup hiçbir ünlü işaretine yer vermemesi', 'Harflerin birbirine bitişmemesi nedeniyle hece sınırlarının tamamen kaybolması', 'Sadece taş ve metal yüzeylere kazınmaya uygun köşeli çizgilerden oluşması'], 'Uygur alfabesinde o/u/ö/ü gibi ünlülerin veya b/p, d/t gibi ünsüzlerin ortak harflerle gösterilmesi okuma güçlüğü yaratmıştır.'),
  ('Uygur alfabesi Türklerin İslamiyet\'i kabulünden sonra dahi hangi Türk-Moğol devletlerinin saray ve resmi yazışmalarında 15. yüzyıl sonlarına kadar kullanılmaya devam etmiştir?', 'Altın Orda, Çağatay ve Timur devletlerinde', ['Büyük Selçuklu, Harzemşah ve Memlük devletlerinde', 'Tolunoğulları, İhşidiler ve Gazneliler devletlerinde', 'Safevi, Afşar ve Kaçar hanedanlıklarında'], 'Cengiz Han sonrası Moğol etkisi ve Türk devlet geleneğiyle Uygur yazısı Timur ve Altın Orda sahasında "Türk yazısı" olarak sürmüştür.'),
  ('Eski Uygur Türkçesi döneminde Budist metinlerin yazımında kullanılan ve hece esasına dayanan Hint kökenli alfabe hangisidir?', 'Brahmi alfabesi', ['Mani alfabesi', 'Nasturi alfabesi', 'İbrani alfabesi'], 'Budist Uygurlar, Sanskritçe terimleri ve dini metinleri doğru yazabilmek için Hint kökenli Brahmi hece yazısını da kullanmışlardır.'),
  ('Uygur Kağanlığı\'nda Bögü Kağan zamanında devlet dini haline gelen Maniheizm\'e ait Türkçe metinlerin yazımında Soğd ve Uygur yazısının yanı sıra hangi alfabe kullanılmıştır?', 'Mani (Maniheist) alfabesi', ['Glagol (Eski Slav) alfabesi', 'Kıpti (Kopt) alfabesi', 'Gürcü (Mhedruli) alfabesi'], 'Maniheist Uygur çevreleri dini eserlerini Estrangelo (Süryani) kökenli Mani alfabesiyle de kaleme almışlardır.'),
  ('Osmanlı İmparatorluğu döneminde Türkçe konuşan Ortodoks Hristiyan Karamanlıların Türkçe eserlerini yazarken kullandıkları alfabe hangisidir?', 'Grek (Yunan) alfabesi', ['Ermeni alfabesi', 'Kiril alfabesi', 'Süryani alfabesi'], 'Anadolu\'daki Türkçe konuşan Ortodoks Karamanlılar, "Karamanlıca" adı verilen yayınlarını Yunan harfleriyle basmışlardır.'),
  ('Arap kökenli Osmanlı Türkçesi alfabesinin Türkçe sözcüklerin okunuşunda belirsizlik yaratmasının en temel yapısal sebebi aşağıdakilerden hangisidir?', 'Türkçedeki sekiz ünlüyü karşılayacak yeterli ünlü harfin bulunmaması', ['Ünsüz harflerin tamamının kelime başında okunmadan düşürülmesi', 'Arap alfabesinde noktalı harflerin hiçbir zaman kelime sonunda yazılmaması', 'Sayıların ve özel isimlerin aynı sembollerle birbirine bitişik gösterilmesi'], 'Türkçe 8 ünlülü zengin bir vokal dilidir; Arap yazısında ise "elif, vav, ye" (ve üstün/esre/ötre) bu ayrımları tam verememiştir.'),
  ('Osmanlı İmparatorluğu\'nda Arap harfli Türk alfabesinin ıslah edilmesi ve okuma-yazmanın kolaylaştırılması konusunu resmi düzeyde gündeme getiren ilk devlet adamı ve aydın (1862) kimdir?', 'Münif Paşa', ['Ahmet Cevdet Paşa', 'Ziya Gökalp', 'Ömer Seyfettin'], 'Münif Paşa, 1862 yılında Cemiyet-i İlmiye-i Osmaniye\'de verdiği konferansta Arap harflerinin ıslahı meselesini ilk kez tartışmaya açmıştır.'),
  ('1923 yılında toplanan İzmir İktisat Kongresi\'nde Latin harflerinin kabul edilmesi yönünde verilen önerge hangi kongre başkanı tarafından "henüz zamanı uygun olmadığı" gerekçesiyle gündeme alınmamıştır?', 'Kazım Karabekir', ['Ali Fuat Cebesoy', 'Rauf Orbay', 'Fethi Okyar'], 'İzmir İktisat Kongresi Başkanı Kazım Karabekir Paşa, ortamın ve şartların henüz olgunlaşmadığını belirterek öneriyi reddetmiştir.'),
  ('Mustafa Kemal Atatürk, Yeni Türk Alfabesi\'ni halka ilk kez 9 Ağustos 1928 akşamı İstanbul\'da düzenlenen hangi etkinlikte müjdelemiştir?', 'Sarayburnu Parkı\'ndaki halk şenliğinde', ['Dolmabahçe Sarayı\'ndaki Dil Kurultayı\'nda', 'Taksim Meydanı\'ndaki Cumhuriyet töreninde', 'Ankara Palas\'taki öğretmenler balosunda'], 'Atatürk, "Arkadaşlar, güzel dilimizi ifade etmek için yeni Türk harflerini kabul ediyoruz" müjdesini 9 Ağustos 1928\'de Sarayburnu\'nda vermiştir.'),
  ('1928 yılında Yeni Türk Alfabesi\'ni hazırlamak üzere Bakanlar Kurulu kararıyla kurulan uzman kurulun resmi adı nedir?', 'Dil Encümeni', ['Encümen-i Daniş', 'Tercüme Bürosu', 'Maarif Şurası'], 'Falih Rıfkı Atay, Yakup Kadri, Ruşen Eşref, Ahmet Cevat Emre ve İhsan Sungu gibi isimlerden oluşan kurul "Dil Encümeni"dir.'),
  ('1928 Yeni Türk Alfabesi oluşturulurken Batı dillerindeki Latin alfabesinde yaygın olarak bulunan "q, w, x" harflerinin alfabeye alınmamasının temel ilkesi nedir?', 'Türkçedeki her sese tek bir harf karşılık gelmesi ve yabancı imla kalıplarının reddedilmesi', ['Matbaa makinelerinde bu üç harfin metal kalıplarının hiçbir ülkede üretilmiyor olması', 'Bu harflerin yalnızca rakam ve matematiksel sembol olarak kullanılmasının zorunlu tutulması', 'Uygur alfabesinden kalan geleneksel harf sayısını aşmama kuralına bağlı kalınması'], 'Yeni Türk Alfabesi fonetik (sesçil) ilkeye dayandırılmış; k, v ve ks sesleri mevcut harflerle karşılandığı için q, w, x dışarıda bırakılmıştır.'),
  ('Sovyetler Birliği yönetimi altındaki Türk cumhuriyet ve özerk bölgelerinde 1920\'lerin sonundaki Latin alfabesi döneminin ardından, 1937-1940 yılları arasında zorunlu olarak hangi alfabeye geçilmiştir?', 'Kiril alfabesine', ['Uygur alfabesine', 'Arap alfabesine', 'Gürcü alfabesine'], 'Stalin döneminde 1937-1940 yılları arasında Sovyetler\'deki Türk topluluklarına farklılaştırılmış Kiril alfabeleri kabul ettirilmiştir.'),
  ('Çarlık Rusyası döneminde 19. yüzyılın ikinci yarısında Hristiyanlaştırılmış Tatarlara (Kreşenlere) ve Kazaklara yönelik misyonerlik faaliyetleri kapsamında Türk lehçelerine Kiril alfabesini ilk uyarlayan Rus şarkiyatçı kimdir?', 'Nikolay İlminskiy', ['Vasily Bartold', 'Vladimir Minorsky', 'Aleksandr Borovkov'], 'Nikolay İlminskiy, 19. yüzyılda Kiril harflerini Türk lehçelerine uyarlayarak yerel lehçeleri ayrı yazı dilleri haline getirme sistemini kurmuştur.'),
  ('Bağımsızlık sonrasında Kiril alfabesinden Latin alfabesine geçiş sürecini 1991-1992 yıllarında ilk başlatan Türk cumhuriyeti hangisidir?', 'Azerbaycan', ['Kırgızistan', 'Kazakistan', 'Tacikistan'], 'Azerbaycan Cumhuriyeti, bağımsızlığının hemen ardından Aralık 1991\'de Latin esaslı yeni alfabeye geçiş kararı almıştır.'),
  ('Yenisey Irmağı boylarında bulunan ve Göktürk (Orhun) alfabesinin erken varyantlarıyla yazılmış mezar taşlarından oluşan yazıt grubuna ne ad verilir?', 'Yenisey Yazıtları', ['Talas Tabletleri', 'Turfan Metinleri', 'Karabalgasun Kitabeleri'], 'Hakasya ve Tuva bölgesinde Yenisey Irmağı çevresinde bulunan mezar taşları Yenisey Yazıtları olarak adlandırılır.'),
  ('"Etimoloji" terimi Eski Yunancada "gerçek, asıl anlam" manasına gelen hangi kök sözcük ile "bilim/söz" anlamındaki "-logia" ekinin birleşiminden doğmuştur?', 'Etymon', ['Ethnos', 'Ethos', 'Entomon'], 'Etimoloji sözcüğü Yunanca "etymon" (gerçek/asıl anlam) ve "logos" (söz, bilim) kelimelerinden türemiştir.'),
  ('15. yüzyılda Çağatay sahasında Ali Şir Nevai tarafından yazılan ve Türkçenin kök türetme gücü ile kelime zenginliği bakımından Farsçadan üstün olduğunu karşılaştırmalı örneklerle ortaya koyan eser hangisidir?', 'Muhakemetü\'l-Lügateyn', ['Mecalisü\'n-Nefais', 'Mizanü\'l-Evzan', 'Garibname'], 'Ali Şir Nevai, Muhakemetü\'l-Lügateyn (İki Dilin Muhakemesi) adlı eserinde Türkçe ve Farsçayı söz varlığı açısından karşılaştırmıştır.'),
  ('Eski Türkçede "her türlü ağaç ve bitki meyvesi" (örneğin elma yemişi, armut yemişi) anlamına gelen "yemiş" sözcüğünün Türkiye Türkçesinde daha çok "incir" veya "kuru kuruyemiş" için kullanılması hangi anlam olayına örnektir?', 'Anlam daralması', ['Anlam genişlemesi', 'Anlam kötüleşmesi', 'Başka dile ödünçleme'], 'Bütün meyveleri kapsayan "yemiş" kelimesinin yalnızca incir ya da çerez türlerini karşılaması açık bir anlam daralmasıdır.'),
  ('Eski Türkçede yaş ve cinsiyet ayrımı gözetmeksizin "insan yavrusu, evlat, çocuk" anlamına gelen "oğlan" kelimesinin sonradan yalnızca "erkek çocuk / genç erkek" anlamında kullanılması hangi anlambilimsel değişmedir?', 'Anlam daralması', ['Anlam genişlemesi', 'Anlam iyileşmesi', 'Deyim aktarması'], 'Hem kız hem erkek çocuğu kapsayan ("kız oğlan" kullanımında izi kalan) "oğlan" sözcüğünün yalnız erkek çocuğa inmesi anlam daralmasıdır.'),
  ('Başlangıçta belirli bir ticari markanın özel adı olan "selpak", "jilet" veya "termos" gibi sözcüklerin zamanla o ürünü üreten tüm markaları kapsayan genel tür adına dönüşmesi hangi anlam olayıdır?', 'Anlam genişlemesi', ['Anlam daralması', 'Anlam kötüleşmesi', 'Ünlü aşınması'], 'Özel bir marka adının (King Camp Gillette -> jilet) bütün tıraş bıçaklarını kapsayan cins adına dönüşmesi anlam genişlemesidir.'),
  ('Eski dönemlerde yalnızca "geminin kıyıya yanaşmasını sağlayan uzatılmış tahta" veya "fıçı/yapı kurmakta kullanılan dikme" anlamındaki Yunanca kökenli "iskele" sözcüğünün zamanla tüm liman tesisini, inşaat çatısını ve anatomik terimleri karşılaması hangi değişmedir?', 'Anlam genişlemesi', ['Anlam daralması', 'Anlam kötüleşmesi', 'Halk etimolojisi'], 'Sınırlı bir merdiven/basamak aracını gösteren kelimenin pek çok alana yayılması anlam genişlemesidir.'),
  ('Eski Türkçede "fena, kötü, sefil, perişan" anlamına gelen "yavlak" ve "yabız (yavuz)" sözcüklerinden "yavuz"un Türkiye Türkçesinde "yiğit, mert, güçlü, çetin" anlamına kavuşması hangi anlam olayıdır?', 'Anlam iyileşmesi', ['Anlam kötüleşmesi', 'Anlam daralması', 'Halk etimolojisi'], 'Divanü Lügati\'t-Türk\'te "yabız/yavuz" doğrudan "kötü, fena" demekken, Anadolu\'da "yiğit, cesur" anlamına yükselerek anlam iyileşmesine uğramıştır.'),
  ('Eski Türkçede "sıkıntı, dert, zahmet, acı, keder" anlamına gelen "emgek (emek)" sözcüğünün zamanla "insanın ortaya koyduğu kutsal ve değerli çalışma gücü" anlamını kazanması hangi değişime örnektir?', 'Anlam iyileşmesi', ['Anlam kötüleşmesi', 'Anlam daralması', 'Kelime birleşmesi'], 'Başlangıçta "eziyet, acı, ıstırap" anlamı taşıyan "emgek" sözcüğü, olumlu ve saygın "emek" kavramına dönüşerek anlam iyileşmesi geçirmiştir.'),
  ('Arapçada "cömert, eli açık, şerefli kimse" anlamına gelen "mübarek" veya Farsçada "canlı, ruh sahibi" anlamındaki "canavar" (can-aver) sözcüğünden "canavar"ın Türkçede "yırtıcı, vahşi, korkunç yaratık" anlamına dönüşmesi hangi olaya örnektir?', 'Anlam kötüleşmesi', ['Anlam iyileşmesi', 'Anlam genişlemesi', 'Ünlü daralması'], 'Farsça "can taşıyan, canlı varlık" (can-aver) gibi nötr/olumlu bir anlamdan "vahşi yaratık, zalim" anlamına geçiş anlam kötüleşmesidir.'),
  ('Farsçada "tüccar başı, esnaf şeyhi, bey, efendi, muhterem zat" gibi saygın bir unvan olan "hace (hoca)" ile bağlantılı "hacegan" veya Arapça "masum, günahsız, zavallı" anlamındaki "miskin" (yoksul, sakin) kelimesinin "uyuşuk, tembel, beceriksiz" (ve eskiden cüzzamlı) anlamını alması nedir?', 'Anlam kötüleşmesi', ['Anlam iyileşmesi', 'Anlam genişlemesi', 'Halk etimolojisi'], 'Arapçada "yoksul, kendi halinde" anlamındaki "miskin" sözcüğünün Türkçede aşağılayıcı biçimde "uyuşuk, tembel" anlamına kayması anlam kötüleşmesidir.'),
  ('Farsça "penbe-dane" (pamuk tanesi / pamuk tohumu) sözcüğünün Türkçede pamukla ilgisi kurulamayıp renginden ötürü "pembe" ve "gön" / "amber" gibi ses çağrışımlarıyla ya da İtalyanca "bailo" (Venedik elçisi) unvanının Türkçede "bayloz / balyoz" ile karıştırılması gibi, "kehribar"ın (< Farsça kehrüba: saman kapan) sonunun "-bar"a dönüşmesi ve "imambayıldı" tipi yakıştırmalardan en tipik örnek olan "kulunç" yerine "kılçık" değil, Farsça "şah-terg / şahtere" yerine "şahtere" gibi, İtalyanca "pomodoro" / Yunanca "domates" değil, Arapça "müdevver" (yuvarlak) yerine "merdane" değil; Farsça "çâr-su" (dört yön / dörtyol ağzı) sözcüğünün "çarşı"ya evrilmesinden farklı olarak, Arapça "tahte\'l-kal\'a" (kale altı) semt adının halk ağzında hangi biçime girmesi halk etimolojisidir?', 'Tahtakale', ['Karaköy', 'Bakırköy', 'Kabataş'], 'Arapça "tahte\'l-kal\'a" (kalenin altı) tamlaması, halk dilinde tanıdık "tahta" ve "kale" sözcüklerine benzetilerek "Tahtakale" yapılmıştır.'),
  ('Arapça ve Farsça "şah-tut" (büyük, iri karadut) tamlamasının Türkçede "şah" kelimesiyle bağı koparılarak soğuk ve buz çağrışımıyla "şहतut" yerine hangi tanıdık Türkçe sıfatla halk etimolojisine uğratıldığı görülür ("karadut" dışındaki yakıştırma örneği olarak "keçiboynuzu" yerine Farsça "har-nup" değil, İngilizce "grapefruit" sözcüğünün Türkçede "greyfurt"a ve halk ağzında "kreyfurt"a dönüşmesi gibi, Farsça "câme-şûy" [çamaşır yıkayan] sözcüğünün "çamaşır" olması yanında, Yunanca "triantafyllo / varil" değil, İtalyanca "lazzaretto" [karantina evi] kelimesinin Türkçede "nezarethane"ye benzetilmesi)?', 'Nezarethane', ['Kütüphane', 'Yemekhane', 'Doğumhane'], 'İtalyanca karantina yeri anlamındaki "lazzaretto" sözcüğü, Arapça "nezaret" ve Farsça "hane" sözcüklerine benzetilerek halk etimolojisine uğramıştır.'),
  ('Farsça "zehr-âb" (zehirli su / acı su) birleşik sözcüğünün halk dilinde ses benzetmesiyle tanıdık bir bitki veya maden adına yaklaştırılarak "çirkef" (< çirk-âb) dışında, Arapça "mülemma" veya İtalyanca "tartaruga" (kaplumbağa) yerine Eski Türkçe "baka" (kurbağa) ile kurulan "kaplumbağa"dan farklı olarak, Farsça "gül-be-şeker" tatlı adının halk ağzında hangi biçime dönüştürülmesi halk etimolojisinin ders kitaplarındaki en bilinen örneğidir?', 'Gülbeşeker yerine "güllaç" değil, "kavanoz" değil; Farsça "şebbû" (gece kokan çiçek) sözcüğünün "şebboy" yapılması', ['Arapça "kitap" sözcüğünün çoğulunun "kütüp" biçiminde çekimlenmesi', 'Türkçe "göz" kökünden "gözlük" ve "gözlem" kelimelerinin türetilmesi', 'Fransızca "tren" kelimesinin sonuna yönelme hali ekinin getirilmesi'], 'Farsça "şeb-bû" (gece kokusu / gece kokan) çiçek adı, halk ağzında Türkçe "boy" kelimesine benzetilerek "şebboy" biçimine sokulmuştur.'),
  ('Arapça "sünger" değil, Farsça "endâze" değil; Arapça "emrûd" / Farsça "emrûd" (armut) kelimesinin yanı sıra, Farsça "aş-pâz" (aş pişiren) sözcüğünün Türkçede meslek yapım eki olan "-çı/-çi"ye benzetilerek hangi biçime girmesi halk etimolojisine örnektir?', 'Aşçıbaşı ve "aşçı"', ['Demirci ve "bakırcı"', 'Sütçü ve "yoğurtçu"', 'Gözcü ve "nöbetçi"'], 'Farsça "aş-pâz" (yemek pişiren) sözcüğü Türkçe "aş" ve "+çı" ekiyle yeniden yorumlanıp halk etimolojisi desteğiyle "aşçı" ile bütünleşmiştir.'),
  ('Arapça "halku\'l-vad" (boğaz küpesi / vadi ağzı) veya Tunus\'taki kalenin adı olan İspanyolca "La Goleta" ile birleşen yer adının Osmanlı denizcileri tarafından "Halkulvad" biçiminde, İstanbul\'daki "San Stefano" semt adının ise halk ağzında ses benzetmesiyle eskiden hangi biçimde söylenmesi halk etimolojisi örneğidir?', 'Ayastefanos', ['Haydarpaşa', 'Kadıköy', 'Üsküdar'], 'Aziz Stefanos anlamına gelen "Hagios Stephanos / San Stefano", halk dilinde "Aya" ile birleşerek "Ayastefanos" biçiminde yerelleştirilmiştir.'),
  ('Yabancı bir dildeki birleşik sözcük veya deyimin sesleriyle doğrudan alınmayıp, onu oluşturan parçaların hedef dildeki karşılıklarıyla birebir tercüme edilerek aktarılmasına (örneğin İngilizce "skyscraper" -> Türkçe "gökdelen") ne ad verilir?', 'Ödünç çeviri (kalk / calque)', ['Halk etimolojisi (yakıştırma)', 'Anlam kötüleşmesi (pejorasyon)', 'Ses göçüşmesi (metatez)'], 'Yabancı bir kelimenin iç yapısının ve anlam modelinin yerli kelimelerle birebir çevrilmesine ödünç çeviri (calque / kalk) denir.'),
  ('Fransızca "chemin de fer" (demir yolu) tamlamasının Türkçeye sesçe "şömendöfer" diye alınmasının yanı sıra "demiryolu" biçiminde sözcüğü sözcüğüne çevrilerek kazandırılması aşağıdakilerden hangisine örnektir?', 'Ödünç çeviri', ['Anlam daralması', 'Anlam kötüleşmesi', 'Ünlü çatışması'], 'Fransızca "chemin" (yol) ve "fer" (demir) öğelerinin Türkçeye "demiryolu" olarak çevrilmesi klasik bir ödünç çeviri (kalk) örneğidir.'),
  ('Aşağıdaki denizcilik ve ticaret terimlerinden hangilerinin tamamı İtalyancadan (Venedik ve Ceneviz lehçeleri dahil) Türkçeye geçmiş ödünç sözcüklerdir?', 'Pusula, kaptan, sigorta, banka, fatura', ['Tengri, subaşı, kurultay, kağan, buyruk', 'Medrese, müderris, kadı, vakıf, imaret', 'Ütü, tugay, kurgan, şölen, toy'], 'Pusula (bussola), kaptan (capitano), sigorta (sicurta), banka (banca) ve fatura (fattura) Türkçeye İtalyancadan geçen ödünçlemelerdir.'),
  ('Osmanlı İmparatorluğu\'nda özellikle Tanzimat Fermanı (1839) sonrasında bürokrasi, modern tıp, mühendislik, ulaşım ve sanat alanlarında Türkçeye en yoğun sözcük veren Batı dili hangisi olmuştur?', 'Fransızca', ['İspanyolca', 'Portekizce', 'Felemenkçe'], '19. yüzyıldan 20. yüzyıl ortalarına kadar diplomasi ve modernleşme dili olan Fransızcadan Türkçeye binlerce kelime ("büro, tren, ekran, roman" vb.) girmiştir.'),
  ('İslamiyet\'in kutsal kitabı Arapça olduğu halde Türkçedeki "namaz" (Arapçası salat), "oruç" (Arapçası savm) ve "abdest" (Arapçası vudu) kelimelerinin Farsça kökenli olmasının tarihsel ve dilbilimsel açıklaması nedir?', 'Türklerin İslam medeniyetiyle ilk yoğun temaslarını İrani topluluklar ve Fars kültür çevresi aracılığıyla kurmuş olması', ['Arapçada ibadet kavramlarını karşılayacak herhangi bir isim veya fiil kökünün bulunmaması', 'Karahanlı hükümdarlarının Arapça kelimelerin yazıda kullanılmasını kanunla yasaklaması', 'Bu sözcüklerin aslında Eski Göktürkçeden Farsçaya geçip hiç değişmeden geri dönmesi'], 'Oğuz ve Karahanlı Türkleri İslamiyet\'i Horasan ve Maveraünnehir\'deki Fars dilli Müslüman komşularından öğrendikleri için bu temel terimleri Farsçadan almışlardır.'),
  ('Türkçede bahçecilik, sebze-meyve, tarım aletleri ve yapı işleriyle ilgili "anahtar, temel, kiremit, tuğla, lahana, pırasa, fasulye, kiraz" gibi sözcükler ağırlıklı olarak hangi dilden alınmıştır?', 'Yunancadan', ['Moğolcadan', 'Macarcadan', 'İngilizceden'], 'Anadolu\'daki yerleşik tarım ve yapı kültürüyle temas sonucunda anahtar (< anoikterion), temel (< themelion), kiremit ve lahana gibi kelimeler Yunancadan geçmiştir.'),
  ('Anadolu\'da yaşayan Ermenilerle yüzyıllar süren komşuluk sonucunda özellikle yerel mutfak, zanaat ve günlük yaşam alanında ("pinti, haşlama/haşıl" tartışmalı olmakla birlikte kesin olarak "örnek, lığ, mertek, çörten, madımak") Türkçeye geçen sözcüklerden en bilinen standart dil kelimesi ("nümunenin" eş anlamlısı olan "örnek" < orinak) hangi dildendir?', 'Ermenice', ['Gürcüce', 'Arnavutça', 'Çerkezce'], 'Standart Türkiye Türkçesinde çok sık kullanılan "örnek" sözcüğü (Eski Anadolu Türkçesinde "örnek/örinek"), Ermenice "orinak" kelimesinden ödünçlenmiştir.'),
  ('Fransızca "kiosque", İngilizce "kiosk" ve Almanca "Kiosk" olarak Batı dillerinde "küçük satış büfesi, çardak, pavilyon" anlamında kullanılan sözcük Türkçedeki hangi kelimeden (Farsça üzerinden Osmanlı kültürüyle) Avrupa\'ya yayılmıştır?', 'Köşk', ['Konak', 'Yalı', 'Kule'], 'Farsçadan Türkçeye geçen ve Osmanlı mimarisiyle Avrupa\'da tanınan Türkçe "köşk" sözcüğü, Batı dillerine "kiosk / kiosque" olarak yerleşmiştir.'),
  ('İngilizce ve Fransızcada kanepe/sedir ve şiir antolojisi anlamlarında kullanılan "divan" ile "sofa" dışındaki, doğrudan Türkçe "yığmak / toplamak / ordu" kavramıyla ilişkili olup Batı dillerine "horde" (İngilizce/Fransızca "kalabalık sürü, göçebe topluluk" - örn. Golden Horde: Altın Orda) biçiminde geçen Türkçe sözcük hangisidir?', 'Ordu', ['Bölük', 'Tabur', 'Sancak'], 'Eski Türkçe "ordu / orda" (kağanın otağı, karargah, askeri güç) sözcüğü Lehçe ve Rusça üzerinden Batı dillerine "horde" olarak geçmiştir.'),
  ('Rusçada para ("dengi" < tenge/damga), gümrük ("tamojnya" < tamga), ütü ("utyug" < ütük), zengin/kahraman ("bogatır" < bagatur/bahadır) gibi sözcüklerin varlığı hangi tarihsel ilişkinin dilbilimsel kanıtıdır?', 'Kıpçak, Bulgar ve Altın Orda Türklerinin Doğu Slavlarıyla yüzyıllar süren siyasi, ticari ve kültürel etkileşiminin', ['Rus Çarlığı\'nın 19. yüzyılda Fransızcadan yaptığı edebi roman tercümelerinin', 'Kiril alfabesinin doğrudan Orhun Yazıtları\'ndaki damgalardan kopyalanmış olmasının', 'Rusçanın 18. yüzyılda Arap alfabesini resmi devlet yazısı olarak kullanmasının'], 'Doğu Slavları ile Hazar, İdil Bulgar, Kıpçak (Kuman) ve Altın Orda Türkleri arasındaki yoğun temas Rusçaya çok sayıda Türkçe kelime kazandırmıştır.'),
  ('Yabancı bir sözcük Türkçeye ödünçlenirken başına bir ünlü getirilmesi olayı (örneğin Fransızca "station" -> "istasyon", İtalyanca "scala" -> "iskele", Rusça "stakan" -> "istikan", Farsça "rûze" -> "oruç") Türkçenin hangi yapısal ses kuralından kaynaklanır?', 'Türkçe kök sözcüklerin başında çift ünsüzün veya "r, l, n, m, ğ" gibi akıcı ünsüzlerin bulunmaması kuralından', ['Türkçede bütün kelimelerin mutlaka dört heceli ve yuvarlak ünlülü olma zorunluluğundan', 'Yabancı kelimelerin sonundaki sert ünsüzlerin her zaman yumuşatılması kuralından', 'Büyük ünlü uyumunun yalnızca kelime sonundaki eklerde geçerli olması ilkesinden'], 'Türkçede kelime başında çift ünsüz (st-, sk-) ve "r-" sesi bulunmadığı için konuşurlar ön seste ünlü türeterek (i-stasyon, o-ruç) kelimeyi Türkçeleştirmiştir.'),
  ('Arapça "kalb, kitâb, mektûb, ilâc" gibi sonu ötümlü (yumuşak) "b, c, d, g" ünsüzleriyle biten ödünç sözcüklerin Türkçede yalın halde "kalp, kitap, mektup, ilaç" biçiminde sertleşerek söylenmesi ve yazılması neyi kanıtlar?', 'Alıntı sözcüklerin Türkçenin "kelime sonunda b, c, d, g bulunmaz" ses kuralına uyarlandığını', ['Arapçada bu kelimelerin tekil ve çoğul biçimlerinin birbirine karıştırıldığını', '1928 Harf İnkılabı sırasında matbaada yumuşak ünsüz harflerin eksik döküldüğünü', 'Bu kelimelerin Türkçeye Arapçadan değil Fransızca üzerinden aktarıldığını'], 'Türkçe sözcük sonunda b, c, d, g ünsüzlerini barındırmadığı için ödünç kelimelerin son seslerini p, ç, t, k olarak ötümsüzleştirmiştir (sertleştirmiştir).'),
  ('Farsça "çâr-şenbih" (dördüncü gün) ve "penc-şenbih" (beşinci gün) birleşik sözcüklerinin Türkçede ünlü uyumu, ünsüz benzeşmesi ve hece kaynaşmasıyla hangi biçimlere evrildiği görülür?', 'Çarşamba ve perşembe', ['Pazartesi ve salı', 'Cuma ve cumartesi', 'Hafta ve gündüz'], 'Farsça "çâr-şenbih" Türkçede "çarşamba"ya, "penc-şenbih" ise n-b > m-b dudaksıllaşması ve ses düşmesiyle "perşembe"ye dönüşmüştür.'),
  ('Türkçedeki "pazartesi" ve "cumartesi" gün adlarının etimolojik oluşum biçimi aşağıdakilerden hangisinde doğru çözümlenmiştir?', '"Pazar ertesi" ve "cuma ertesi" tamlamalarının ünlü ve ünsüz aşınmasıyla birleşmesi', ['Farsça "bâzâr" ve "cemaat" kelimelerine Rumca sıra sayı eklerinin getirilmesi', 'Eski Türkçe "ertemek" fiilinin şimdiki zaman çekimiyle kalıplaşması', 'Arapça iki ayrı zaman zarfının halk etimolojisiyle ters çevrilmesi'], '"Ertesi" (arkası, sonraki gün) sözcüğüyle kurulan "pazar ertesi > pazartesi" ve "cuma ertesi > cumartesi" birleşik kelimeleri aşınma yoluyla kaynaşmıştır.'),
  ('Günlük dilde sıkça kullanılan "peki" onaylama sözcüğünün etimolojik açıdan asıl birleşim biçimi aşağıdakilerden hangisidir?', 'Pek + iyi', ['Pey + ki', 'Pekiştirme + ki', 'Baş + göz'], '"Pek iyi" söz öbeği konuşma dilinde aradaki "y" ve dar ünlülerin aşınıp kaynaşmasıyla "peki" şeklini almıştır.'),
  ('"Sütlaç" tatlısının adının etimolojik gelişim basamakları aşağıdakilerden hangisinde doğru olarak verilmiştir?', 'Sütlü aş > sütlaş > sütlaç', ['Süt ilacı > sütlaç', 'Sütlü ağaç > sütlaç', 'Su ve taç > sütlaç'], 'Divanü Lügati\'t-Türk\'te "sütlüg aş" olarak geçen yemek adı, ünlü düşmesi ve son sesteki ş > ç değişimiyle "sütlaç" olmuştur (halk arasında "sütlü aş" bağı unutulmuştur).'),
  ('"Kaynana" ve "kaynata" sözcüklerinin başındaki "kayın-" öğesi ile bağlantılı olarak, "kaynana" kelimesi hangi birleşim ve ses olayıyla oluşmuştur?', 'Kayın + ana birleşiminde orta hece ünlüsünün düşmesiyle', ['Kaynamak fiil köküne "-ana" sıfat-fiil ekinin eklenmesiyle', 'Kadın + nine sözcüklerinin halk etimolojisiyle yer değiştirmesiyle', 'Kardeş + anne tamlamasının ünlü daralmasına uğramasıyla'], 'Eski Türkçe "kadın" (evlilik yoluyla akraba -> kayın) ve "ana" kelimelerinin birleşmesi ("kayın ana"), orta hecedeki "ı"nın düşmesiyle "kaynana" olmuştur.'),
  ('"Ayakkabı" sözcüğünün sonundaki "-ı" ünlüsünün etimolojik ve dilbilgisel işlevi nedir?', '"Ayak kabı" belirtisiz isim tamlamasından kalan 3. tekil kişi iyelik ekidir', ['Fiilden isim türeten işlek bir yapım ekidir', 'Arapça nispet ekinin kalın ünlülere uyarlanmış biçimidir', 'Yabancı kelimelerin sonuna getirilen ses türemesidir'], '"Ayak" ve "kap" (kılıf, muhafaza) kelimelerinden kurulan belirtisiz isim tamlaması ("ayak kab-ı") kalıplaşarak tek sözcük haline gelmiştir.'),
  ('Eski Türkçede "edgü" (iyi), "adak" (ayak), "kod-" (koymak), "kudruk" (kuyruk) biçiminde "d" (veya peltek d) sesiyle yazılan sözcüklerin Türkiye Türkçesinde "iyi, ayak, koy-, kuyruk" biçiminde olması hangi tarihsel ses yasasını gösterir?', 'Eski Türkçedeki kelime içi ve sonu d sesinin Oğuz ve Kıpçak gruplarında y sesine dönüşmesini', ['Bütün Türkçe fiil köklerinin tek heceli ünlülerden ünsüz türetmesiyle kurulduğunu', 'Arap alfabesindeki "dal" harfinin 1928\'de tamamen alfabeden çıkarıldığını', 'Anlam genişlemesi sonucunda organ adlarının soyut sıfatlara dönüştüğünü'], 'Türk dil tarihinde boyları tasnif etmede en önemli ölçütlerden biri Eski Türkçe "adak" kelimesindeki d\'nin Türkiye Türkçesinde "ayak" (y), Tuva\'da "adak" (d), Yakutçada "atah" (t), Hakasçada "azah" (z) olmasıdır.'),
  ('Türkiye Türkçesindeki "öğretmen, öğrenci, subay, kurmay, yargıç, uçak, bilgisayar" gibi sözcüklerin Türk dil tarihindeki ortak özelliği nedir?', 'Cumhuriyet dönemi Dil Devrimi ve Türkçeleştirme çalışmalarıyla Türkçe kök ve eklerden türetilmiş yeni sözcükler (neolojizm) olmaları', ['Orhun Yazıtları\'nda hiçbir ses değişikliğine uğramadan bugünkü yazılışlarıyla yer almaları', 'Tanzimat döneminde Fransızcadan ses benzetmesiyle alınmış alıntılar olmaları', 'Arapça ve Farsça tamlamaların halk ağzında bozulmuş biçimleri olmaları'], '1932\'de Türk Dili Tetkik Cemiyeti\'nin (TDK) kurulmasıyla birlikte "muallim -> öğretmen", "tayyare -> uçak", "hakim -> yargıç" gibi yeni türetmeler dile kazandırılmıştır.'),
  ('Eski Türkçede "uçmak" fiilinden türeyen veya Soğdca "uştmah" (cennet) ödünçlemesinin Türkçe "uçmak" fiiliyle sesçe birleşmesi sonucu Eski Anadolu Türkçesinde "cennet" anlamında "uçmak / uçmağ" ("Uçmağa varmak": vefat edip cennete gitmek) olarak kullanılan sözcük, hangi iki etimolojik olgunun kesişimine örnektir?', 'Ödünçleme (Soğdca uştmah) ve yerli fiil köküne ("uç-") benzetilerek yapılan halk etimolojisi', ['Anlam kötüleşmesi ve Kiril alfabesinden kaynaklanan imla karışıklığı', 'Ödünç çeviri (kalk) ve sözcük başında ünlü türemesi', 'Anlam daralması ve ünsüz ikizleşmesi'], 'Soğdca "uştmah" (cennet) sözcüğü Türkçeye alındığında, Türkler tarafından ruhun göğe "uçması" (uç-mak) fiiliyle ilişkilendirilerek halk etimolojisiyle yerlileştirilmiştir.'),
  ('Türkiye Türkçesinde "göz" organ adından türetilmiş olan "gözlük, gözcü, gözlem, gözde, gözenek, gözetlemek" sözcükleri Türkçenin etimolojik ve biçimbilimsel olarak hangi tip dil olduğunu açıkça gösterir?', 'Sوندan eklemeli (bitişken / aglütinatif) ve kökü değişmeyen bir dil olduğunu', ['Kelime kökündeki ünlülerin bükülerek değiştiği bükümlü bir dil olduğunu', 'Hiçbir yapım veya çekim eki kullanmayan tek heceli (yalınlayan) bir dil olduğunu', 'Yalnızca ön eklerle (prefiks) yeni sözcük türeten bir dil olduğunu'], 'Türkçe sondan eklemeli bir dildir; "göz" kökü sabit kalırken sona gelen yapım ekleriyle zengin bir sözcük ailesi türetilir.'),
  ('Türkçedeki "kızamık, kızıl, kızarmak, kızgın, kızmak" sözcüklerinin tamamının ortak etimolojik kökü hangi kavramla doğrudan ilişkilidir?', 'Ateş rengi / kırmızı ve ısınarak kor haline gelmek', ['Kız çocuğu ve aile içi akrabalık bağları', 'Kısa olmak ve boyca küçülmek', 'Kış mevsimi ve dondurucu soğuk'], 'Eski Türkçe "kız-" (kırmızı olmak, kor gibi ısınmak) fiil kökü ile "kızıl" rengi; öfke ("kızgın") ve döküntülü hastalık ("kızamık") anlamlarını türetmiştir.'),
  ('"Darılmak" ve "dar" sözcükleri arasındaki etimolojik ilişki düşünüldüğünde, "darılmak" fiilinin ilk somut anlamından bugünkü "gücenmek, küsmek" soyut anlamına geçişi nasıl gerçekleşmiştir?', '"Dar" kökünden "içi, gönlü sıkışmak / daralmak" somut-fiziksel çağrışımının duygusal gücenme anlamına evrilmesiyle', ['"Darı" tahıl adının tarlada biçilmesi eyleminin halk etimolojisine uğramasıyla', 'Arapça "darb" (vurmak) kökünün anlam iyileşmesi geçirerek nezaket bildirmesiyle', 'İtalyanca bir ticaret teriminin denizciler aracılığıyla Anadolu\'ya yayılmasıyla'], '"Dar" isminden türeyen "dar-ı-l-mak", insanın içinin/göğsünün sıkıntıdan "daralması" metaforuyla "gücenmek, küsmek" anlamını kazanmıştır.'),
  ('Eski Türkçede "yok" kökünden türeyen "yoksul" (< yok+suz / yok+sul) sözcüğü gibi, "öksüz" sözcüğünün başındaki unutulmuş "ök" isim kökü Eski Türkçede hangi anlama gelmekteydi?', 'Anne (ana)', ['Baba (ata)', 'Ekmek (aş)', 'Ev (otağ)'], 'Eski Türkçede "ök" sözcüğü "anne" demektir; "ök+süz" tam olarak "annesiz kalan çocuk" anlamına gelir (sonradan yetimle yakınlaşmıştır).'),
  ('"Arkadaş" sözcüğünün etimolojik yapısı ("arka + daş") eski Türk savaş ve toplumsal yaşamındaki hangi somut durumdan soyut dostluk anlamına evrilmiştir?', 'Savaşta ve tehlikede birbirine "arka" (sırt) vererek birbirini koruyan yoldaşlar olma durumundan', ['Aynı kafilede kervanın en "arka" sırasından yürüyen yolcular olma durumundan', 'Arapça "ark" (su kanalı) kelimesinden aynı tarlayı sulayan komşular olma durumundan', 'Eski Uygur metinlerinin arka sayfasına adını yazdıran katipler olma durumundan'], 'Birbirine sırtını ("arkasını") dayayarak güvenen ve omuz omuza çarpışan kimseler için "arka+daş" denilmiş, buradan "dost" anlamı yerleşmiştir.'),
  ('Eski Türkçede "yüz" (sayı olan 100), "yüz" (çehre, surat), "yüz-" (suda yüzmek) ve "yüz-" (derisini yüzmek) sözcüklerinin aynı yazılması dilbilim ve etimolojide ne tür sözcüklere örnektir?', 'Kökenleri farklı eş sesli (sesteş / homonim) sözcüklere', ['Aynı kökten anlam daralmasıyla ayrılmış eş anlamlı sözcüklere', 'Yabancı dillerden alınmış ödünç çeviri sözcüklere', 'Halk etimolojisiyle bozulmuş ikileme sözcüklere'], 'Aralarında anlam bağı bulunmayan bu ayrı kökler, eş sesli (sesteş) sözcüklerin Türkçedeki en karakteristik örneğidir.'),
  ('"Odun" ve "ocak" sözcüklerinin etimolojik olarak hangi eski Türkçe kök sözcükten türediği kabul edilir?', '"Ateş" anlamına gelen "od (ot)" kökünden', ['"Oda" anlamına gelen "otağ" sözcüğünden', '"Odak" anlamına gelen Fransızca kökten', '"Oyun" anlamına gelen fiil gövdesinden'], 'Eski Türkçe "ōt > od" (ateş) kökünden yakacak malzemesi olarak "odun" ve ateşin yakıldığı yer olarak "ocak" (< od+çak / oçak) türemiştir.'),
  ('Eski Türklerde bitkisel ilaçlarla hastaları tedavi eden hekimlere "ot" (bitki, ilaç) kökünden türetilerek hangi ad verilmekteydi?', 'Otacı', ['Subaşı', 'Tudun', 'Yargucu'], 'Eski Türkçede "ot" hem bitki hem de bitkisel ilaç demekti; "otacı" (ve "em" = ilaç kökünden "emçi") hekim, tabip anlamına gelirdi.'),
  ('"Düğün" sözcüğünün Eski Türkçede "tügün" (düğüm; bağlamak) veya "döğün / tögün" ile ses benzerliği yanında, Divanü Lügati\'t-Türk\'te "toy" ve "küdegü" (güvey) ile birlikte eğlence/ziyafet bağlamında incelenmesinin ötesinde; "güvey" sözcüğü Eski Türkçedeki hangi kelimenin ses değişimine uğramış biçimidir?', 'Küdegü', ['Karındaş', 'Künçüy', 'Kölük'], 'Eski Türkçede damat anlamına gelen "küdegü" sözcüğü, k > g ötümlüleşmesi ve iç/son sesteki d, g erimeleriyle Türkiye Türkçesinde "güvey" (güveyi) olmuştur.'),
  ('Türkçedeki "yılkı" (başıboş at sürüsü), "yular", "eyer" (< edger) ve "üzengi" (< üzengü) gibi atçılık terimlerinin tamamının Türkçe kökenli olması etimoloji ile kültür tarihi arasındaki hangi ilkeyi doğrular?', 'Bir ulusun yaşam biçiminde merkezde yer alan kültürel unsurların (bozkır atlı kültürü) söz varlığının yerli köklerden oluştuğunu', ['Atçılıkla ilgili bütün kelimelerin yerleşik denizci kavimlerden ödünç alındığını', 'Hayvancılık terimlerinin hiçbir zaman ses değişmesine uğramadan korunduğunu', 'Göçebe toplumların kendi dillerinde soyut veya somut isim türetemediğini'], 'Bir toplumun uzmanlaştığı temel kültür alanındaki (Türklerde at ve bozkır kültürü) çekirdek söz varlığı yabancı dillerden alınmaz, öz köklerden türetilir.'),
  ('Türkçede "kalp" (Arapça) ve "yürek" (Türkçe), "sene" (Arapça) ve "yıl" (Türkçe), "siyah" (Farsça) ve "kara" (Türkçe), "beyaz" (Arapça) ve "ak" (Türkçe) çiftlerinin bir arada yaşaması ve deyimlerde ("kara gün, ak alın, yüreği yanmak") yerli olanların tercih edilmesi nasıl değerlendirilir?', 'Ödünç sözcüklerle yerli sözcüklerin nüans ve kullanım alanı paylaşımıyla dilin ifade zenginliğini artırdığı, deyimlerin ise öz Türkçe kökleri koruduğu', ['Ödünç alınan her kelimenin yerli kelimeyi dilden bir hafta içinde tamamen sildiği', '"Ak, kara, yıl, yürek" kelimelerinin aslında Fransızcadan yakın dönemde dilimize girdiği', 'Eş anlamlı kelimelerin tamamının halk etimolojisi hatası sonucu ortaya çıktığı'], 'Siyah/kara veya beyaz/ak çiftlerinde alıntı kelimeler çoğu kez nötr renk adı olurken, öz Türkçe "ak" ve "kara" deyim ve mecaz yükünü ("yüz akı, kara haber") taşımaya devam etmiştir.'),
  ('Sabah selamlaşması olarak kullanılan "günaydın" ve akşamüstü selamlaşması olan "tünaydın" sözcüklerinden "tünaydın"ın başındaki "tün" kelimesi Eski Türkçede ne anlama gelmektedir?', 'Gece / akşam karanlığı', ['Sabah güneşi', 'Öğle sıcağı', 'İlkbahar yağmuru'], 'Eski Türkçede "kün (gün)" gündüz ve güneş, "tün" ise gece demektir ("dün" kelimesi de "geçen gece / tün"den gelir); "tünaydın" geceniz/akşamınız aydın olsun anlamında türetilmiştir.'),
  ('"Yarın" sözcüğünün Eski Türkçede "aydınlanmak, ışımak, sabah olmak" anlamına gelen hangi fiil köküyle ("yaruk": ışık, aydınlık) aynı etimolojik aileden türediği bilinmektedir?', '"Işımak, tan ağarmak" anlamındaki "yaru- (yarımak)" fiiliyle', ['"Ortadan ikiye bölmek" anlamındaki "yar- (yarmak)" fiiliyle', '"Fayda sağlamak" anlamındaki "yara- (yaramak)" fiiliyle', '"Yardım etmek" anlamındaki Farsça "yâr" ismiyle'], 'Eski Türkçe "yaru-" (aydınlanmak, şafak sökmek) kökünden gelen "yarın", başlangıçta "sabah vakti, tan ağardığında" demekken "ertesi gün" anlamına yerleşmiştir.'),
  ('Orhun Yazıtları\'nda geçen "tengri, sub (su), yer, kün (gün), tün (gece), oglan, bodun, bilge, sab (sav/söz)" gibi sözcüklerin büyük çoğunluğunun küçük ses farklarıyla Türkiye Türkçesinde de anlaşılır biçimde yaşaması neyin göstergesidir?', 'Türkçenin bin yılı aşkın yazılı tarihinde yüksek bir sözlüksel ve yapısal sürekliliğe sahip köklü bir dil olduğunun', ['Orhun Yazıtları\'nın aslında 19. yüzyılda İstanbul Türkçesiyle kaleme alınmış modern metinler olduğunun', 'Dilimizde hiçbir dönemde anlam daralması, anlam genişlemesi veya ses değişmesi yaşanmadığının', 'Göktürk alfabesiyle Yeni Türk Alfabesi\'nin harf şekillerinin birebir aynı olduğunun'], '8. yüzyıl Orhun metinlerindeki temel kelimelerin bugün hala canlı olması, Türk dilinin tarihsel sürekliliğini kanıtlar.'),
  ('Aşağıdaki sözcük çiftlerinden hangisi "birleşik sözcüğün ses aşınmasıyla tek kelime haline gelmesi" sürecine örnek oluşturmaz?', 'Gözlük (< göz + lük)', ['Pazartesi (< pazar + ertesi)', 'Kahvaltı (< kahve + altı)', 'Sütlaç (< sütlü + aş)'], 'Pazartesi, kahvaltı ve sütlaç iki ayrı sözcüğün aşınarak kaynaşmasıyla oluşmuşken; "gözlük" tek bir isim kökünden yapım ekiyle türetilmiş türemiş sözcüktür.'),
  ('İngilizce "She eventually found a job in Izmir." cümlesindeki "eventually" zarfı Türkçeye nasıl aktarılmalıdır?', 'Sonunda / nihayetinde', ['Tesadüfen / şans eseri', 'Muhtemelen / belki', 'Geçici bir süreliğine'], '"Eventually" uzun bir süreç veya çabanın sonunda, nihayet anlamındadır; Fransızca "éventuellement" (muhtemelen/gerekirse) ile yalancı eşdeğerdir.'),
  ('"The Minister denied the rumour, saying the actual figures were much lower." cümlesinde "actual figures" ifadesi neyi anlatmaktadır?', 'Gerçek / fiili rakamları', ['En son güncellenen tahminleri', 'Gelecek yıla ait projeksiyonları', 'Basına sızdırılan sahte verileri'], '"Actual" sözcüğü "güncel" değil "gerçek, asıl, fiili" anlamına geldiğinden "actual figures" gerçek rakamlar demektir.'),
  ('Bir konferansta yalnızca bir veya iki yabancı konuk bulunduğunda, çevirmenin kabin kullanmadan konuğun yanına oturup kısık sesle eşzamanlı çeviri yapmasına ne ad verilir?', 'Fısıltı çevirisi', ['Ardıl kürsü çevirisi', 'Eşlik (refakat) çevirisi', 'Telefon üzerinden aracılı çeviri'], 'Fransızca fısıldamak kökünden gelen "chuchotage", az sayıda dinleyiciye mikrofon ve kabin olmaksızın yapılan eşzamanlı fısıltı çevirisidir.'),
  ('Yazılım ve oyun yerelleştirme sektöründe sıklıkla kullanılan "L10n" kısaltmasındaki "10" sayısı neyi temsil eder?', '"Localization" sözcüğünün ilk ve son harfleri arasındaki on harfi', ['Yerelleştirme sürecinin on temel kalite kontrol aşamasını', 'Bir yazılımın en az on farklı dile çevrilme zorunluluğunu', 'Uluslararası standartlar örgütünün on numaralı çeviri protokolünü'], 'Numeronim kuralına göre "Localization" kelimesinde başındaki "L" ile sonundaki "n" harfleri arasında 10 harf bulunduğu için "L10n" yazılır.'),
  ('İngilizce "cold war" ifadesinin Türkçeye "soğuk savaş", "brainwashing" ifadesinin ise "beyin yıkama" olarak yerleşmesi hangi çeviri olgusuna örnektir?', 'Öyküntü (calque)', ['Yalancı eşdeğerlik (false friends)', 'Fonetik ödünçleme (loanword)', 'Kültürel yerelleştirme (domestication)'], 'Kaynak dildeki tamlamanın bileşenlerinin hedef dile birebir çevrilerek yeni bir kalıp oluşturulması öyküntüdür (calque).'),
  ('İngilizce "agenda" sözcüğü "What is the next item on the agenda?" cümlesinde hangi anlamda kullanılmıştır?', 'Toplantı gündemi', ['Deri kaplı not defteri', 'Masaüstü takvim çizelgesi', 'Kişisel telefon rehberi'], 'Türkçede "ajanda" takvimli not defteri için kullanılırken, İngilizcede "agenda" bir toplantıda görüşülecek konular listesi yani "gündem" demektir (not defteri: diary/planner).'),
  ('İngilizce "assist" fiili "Several nurses assisted the surgeon during the operation." cümlesinde ne anlama gelir?', 'Yardım etmek / asistanlık yapmak', ['Sadece izleyici olarak katılmak', 'Operasyonu uzaktan denetlemek', 'Tutanak tutarak onaylamak'], 'İngilizcede "assist" yardım etmek demektir; Fransızca "assister à" veya İspanyolca "asistir a" ise "bir etkinliğe katılmak/hazır bulunmak" anlamındadır.'),
  ('Fransızca "J\'ai assisté à la conférence hier soir." cümlesini Türkçeye çeviren bir öğrencinin "Dün akşam konferansa yardım ettim." demesi hangi kavramdan kaynaklanan bir hatadır?', 'Diller arası yalancı eşdeğerlik', ['Kaynak metindeki deyimin öyküntü yoluyla aktarılması', 'Erek dilde sözcüksel boşluk (lacuna) bulunması', 'Eşzamanlı çeviride kulaklık gecikmesi (décalage) yaşanması'], 'Fransızcada "assister à quelque chose" bir yerde hazır bulunmak, katılmak demektir; İngilizce "assist" (yardım etmek) ile yalancı eşdeğerdir.'),
  ('İngilizce "conductor" sözcüğü "The conductor raised his baton and the symphony began." cümlesinde kimi ifade etmektedir?', 'Orkestra şefini', ['Bilet kontrol memurunu', 'Yüksek gerilim kablosunu', 'Tren makinist yardımcısını'], '"Conductor" müzik bağlamında orkestra şefi (ulaşımda biletçi, fizikte iletken) demektir; Türkçede yalnızca "kondüktör" (biletçi) olarak düşünmek yanıltıcıdır.'),
  ('İngilizce "preservative" sözcüğü bir gıda paketinin içindekiler kısmında yer aldığında Türkçeye nasıl çevrilmelidir?', 'Koruyucu katkı maddesi', ['Doğum kontrol aracı', 'Reçel ve marmelat özütü', 'Nem alıcı silika jel'], 'İngilizcede "preservative" gıdaların bozulmasını önleyen koruyucu madde demektir; birçok Avrupa dilindeki (Fr. préservatif, Alm. Präservativ) anlamı ise İngilizcede "condom"dur.'),
  ('İngilizce "pathetic" sıfatı günlük konuşmada "That was a pathetic excuse!" cümlesinde hangi anlamı taşır?', 'Acınası / zavallıca / çok yetersiz', ['Son derece duygusal ve şiirsel', 'Tıbbi açıdan bulaşıcı hastalık taşıyan', 'Sempatik ve ikna edici'], 'Yunanca "pathos" kökünden gelse de modern İngilizcede "pathetic" zavallı, acınacak halde, gülünç derecede yetersiz anlamında olumsuz kullanılır.'),
  ('İngilizce "nervous" sıfatı "I always feel nervous before a job interview." cümlesinde hangi duygu durumunu anlatır?', 'Heyecanlı / gergin / kaygılı', ['Çok öfkeli ve kavgacı', 'Ruhsal bunalıma girmiş', 'Aşırı kibirli ve soğuk'], 'Türkçedeki "sinirli" (öfkeli/kızgın -> angry/irritable) anlamının aksine İngilizce "nervous" sınav veya mülakat öncesi duyulan endişe, heyecan ve gerginliği ifade eder.'),
  ('İngilizce "lunatic" sözcüğünün etimolojik kökeni olan Latince "luna" (ay) kelimesiyle ilişkisi düşünüldüğünde sözcüğün İngilizcedeki anlamı nedir?', 'Akıl sağlığı yerinde olmayan / çılgın kimse', ['Ay yüzeyini inceleyen gökbilimci', 'Gece vardiyasında çalışan fabrika işçisi', 'Romantik ve hayalperest şair'], 'Eskiden ayın evrelerinin deliliğe yol açtığına inanıldığı için "lunatic" sözcüğü İngilizcede "deli, kaçık, çılgın" anlamında yerleşmiştir.'),
  ('Bir ABD şirketinin web sitesindeki "Shipping scheduled for 04/09" ifadesini Türkiye\'deki kullanıcılar için yerelleştiren bir çevirmen tarihi gün/ay sırasıyla nasıl yazmalıdır?', '09.04 (9 Nisan)', ['04.09 (4 Eylül)', '09.09 (9 Eylül)', '04.04 (4 Nisan)'], 'ABD tarih formatı Ay/Gün (MM/DD) şeklindedir; dolayısıyla "04/09" 9 Nisan\'ı ifade eder ve Türkiye yerelleştirmesinde Gün.Ay (09.04) olarak dönüştürülmelidir.'),
  ('"Please handle this delicate glass vase; it is very ______ to sudden temperature changes." boşluğuna bağlama en uygun İngilizce sıfat hangisidir?', 'sensitive', ['sensible', 'sympathetic', 'subsequent'], 'Isı değişimlerine karşı "duyarlı/hassas" anlamını "sensitive" verir; "sensible" yalnızca akla uygun, mantıklı demektir.'),
  ('İngilizceden Türkçeye çeviri yapan bir çevirmen "He bought three cartons of milk and a comic cartoon book." cümlesini nasıl çevirmelidir?', 'Üç karton kutu süt ve bir mizahi karikatür kitabı satın aldı.', ['Üç çizgi film CD\'si ve sütlü bir karton kutu satın aldı.', 'Üç şişe süt ve kalın mukavva kapaklı bir roman satın aldı.', 'Üç paket krema ve resimli bir mağaza kataloğu satın aldı.'], 'İngilizcede sıvı/gıda ambalajı olan kutu "carton", karikatür veya çizgi film ise "cartoon" ile ifade edilir.'),
  ('Bir hukuk çevirmeni sözleşmedeki "in the event of a dispute, the eventual cost will be shared" ifadesinde geçen "eventual cost" tamlamasını nasıl karşılamalıdır?', 'Nihai (sonuçta ortaya çıkacak) maliyet', ['Olası (ihtimal dahilindeki) ek vergi', 'Güncel piyasa rayiç bedeli', 'Geçmiş dönemlerden devreden borç'], '"Eventual" bir sürecin sonunda gerçekleşecek olan, nihai demektir; olasılık bildiren sözcük "possible" veya "potential"dır.'),
  ('Bir tıp kongresinde eşzamanlı çeviri yapan tercüman "The physician prescribed a new drug." cümlesini Türkçeye aktarırken "physician" sözcüğünü nasıl çevirmelidir?', 'Tıp doktoru / hekim', ['Kuantum fizikçisi', 'Eczane kalfası', 'Fizyoterapi uzmanı'], '"Physician" tıp doktoru/hekim demektir; fizik bilimiyle uğraşan "fizikçi" İngilizcede "physicist" olarak adlandırılır.'),
  ('Almanca bilen bir öğrencinin İngilizce "She gave him a small gift." cümlesini Almancadaki "Gift" sözcüğünün etkisinde kalarak yanlış çevirmesi durumunda ortaya hangi anlam çıkar?', 'Ona küçük bir miktar zehir verdi.', ['Ona evlilik çeyizi olarak altın verdi.', 'Ona imzalı bir veda mektubu verdi.', 'Ona borç olarak bir miktar para verdi.'], 'Aynı Germen kökünden ("vermek/doz") türeyen "gift" İngilizcede "hediye" iken Almancada "zehir" anlamına gelen klasik bir yalancı eşdeğerdir.'),
  ('İspanyolca öğrenen bir İngiliz turistin utanıp sıkıldığını söylemek isterken İspanyolca "Estoy embarazada." demesi İspanyolca konuşanlarda nasıl anlaşılır?', 'Hamileyim.', ['Çok mahcubum ve özür dilerim.', 'Cüzdanımı otobüste düşürdüm.', 'Yabancı dil bilmiyorum.'], 'İngilizce "embarrassed" (utanmış/mahcup) ile İspanyolca "embarazada" (hamile) ünlü bir yalancı eşdeğer çiftidir; İspanyolcada utanmış "avergonzado/a"dır.'),
  ('Aşağıdaki İngilizce-Türkçe sözcük eşleştirmelerinden hangisi yalancı eşdeğer (false friend) tuzağına düşülmeden DOĞRU verilmiştir?', 'accurate -> doğru / kesin / hatasız', ['fabric -> ağır sanayi fabrikası', 'sympathetic -> sevimli / cana yakın', 'actual -> güncel / aktüel'], '"Accurate" doğru, tam, hatasız demektir; diğer seçeneklerdeki sözcükler Türkçedeki benzer sesli karşılıklarıyla karıştırılmıştır.'),
  ('Bir çevirmenin kaynak metindeki "It rains cats and dogs." deyimini Türkçeye "Kedi ve köpek yağıyor." yerine "Bardaktan boşanırcasına yağmur yağıyor." biçiminde çevirmesi hangi ilkeyle açıklanır?', 'İşlevsel ve deyimsel eşdeğerlik sağlama', ['Öyküntü (calque) yoluyla yeni terim türetme', 'Kaynak dil odaklı yabancılaştırma stratejisi', 'Sözcüğü sözcüğüne biçimsel aktarım yapma'], 'Deyimlerin kaynak dildeki imgelerini birebir çevirmek yerine erek dilde aynı iletişimsel işlevi gören yerleşik deyimi kullanmak işlevsel/deyimsel eşdeğerliktir.'),
  ('Eşzamanlı (simultane) çeviri ile ardıl (konsekütif) çeviri karşılaştırıldığında aşağıdakilerden hangisi ardıl çeviriyi eşzamanlı çeviriden ayıran temel özelliktir?', 'Konuşma süresini yaklaşık iki katına çıkarması ve özel kabin donanımı gerektirmemesi', ['Aynı anda beş farklı dile gecikmesiz olarak aktarım imkanı sunması', 'Çevirmenin konuşmacıyı dinlerken aynı saniyede konuşmasını zorunlu kılması', 'Yalnızca yazılı sözleşme metinlerinin noter huzurunda okunmasında kullanılması'], 'Ardıl çeviride önce konuşmacı konuşur, sonra çevirmen notlarından aktarır; bu durum teknik kabin ihtiyacını ortadan kaldırır ancak toplantı süresini uzatır.'),
  ('Bir yazılım firmasının ürününü daha kodlama aşamasındayken farklı alfabeleri (UTF-8), sağdan sola yazılan dilleri ve değişen metin uzunluklarını destekleyecek esneklikte tasarlamasına ne ad verilir?', 'Uluslararasılaştırma (internationalization - i18n)', ['Görsel-işitsel altyazı senkronizasyonu', 'Sözcüksel öyküntüleme (lexical calque)', 'Ardıl toplum çevirmenliği (community interpreting)'], 'Uluslararasılaştırma (i18n), yazılım mimarisinin kaynak kodda değişiklik gerektirmeden sonraki yerelleştirme (L10n) işlemlerine hazır hale getirilmesidir.'),
  ('Türkçedeki "bilgisayar" sözcüğü İngilizce "computer" karşılığında "bilgi + sayar" köklerinden türetilmiştir; "fare" sözcüğü ise İngilizce "mouse" teriminin bilişimdeki yan anlamının Türkçedeki "fare" kelimesine yüklenmesiyle oluşmuştur. Bu ikinci durum çeviribilimde ne olarak adlandırılır?', 'Anlamsal öyküntü (semantic calque / loan shift)', ['Fonetik doğrudan ödünçleme (direct loanword)', 'Yalancı eşdeğerlik sapması (false cognate)', 'Kısaltma yoluyla sözcük türetimi (acronym)'], 'Dilde zaten var olan bir sözcüğe (fare) yabancı dildeki karşılığının (mouse) yeni mecazi/teknik anlamının aktarılmasına anlamsal öyküntü denir.'),
  ('İngilizce "comprehensive" ile "comprehensible" sıfatları sıklıkla hem kendi aralarında hem de başka dillerdeki benzerleriyle karıştırılır. Bu iki sözcüğün doğru anlam ayrımı hangisidir?', 'Comprehensive: kapsamlı / geniş çaplı — Comprehensible: anlaşılabilir', ['Comprehensive: anlaşılabilir — Comprehensible: aşırı duygusal ve alıngan', 'Comprehensive: özetlenmiş / kısa — Comprehensible: zorunlu / mecburi', 'Comprehensive: hoşgörülü / şefkatli — Comprehensible: kapsamlı / detaylı'], '"Comprehensive" her yönü içeren, kapsamlı demektir (Fr. compréhensif ise anlayışlı anlamında yalancı eşdeğerdir); "comprehensible" ise anlaşılabilir demektir.'),
  ('İngilizce "collar" sözcüğü "white-collar workers" tamlamasında Türkçeye "beyaz yakalı çalışanlar" olarak çevrilmiştir. Buradaki hem sözcük anlamı hem de tamlamanın Türkçeye geçiş biçimi için hangisi doğrudur?', '"Collar" yaka demektir ("kol" değil); tamlama Türkçeye öyküntü (calque) yoluyla geçmiştir.', ['"Collar" gömlek kolu demektir; Türkçeye çevrilirken kültürel yerelleştirme yapılmıştır.', '"Collar" kravat demektir; tamlama ses aktarımı (transkripsiyon) yoluyla yerleşmiştir.', '"Collar" kolye demektir; tamlama yalancı eşdeğerlik hatası sonucu yanlış çevrilmiştir.'], 'İngilizce "collar" Türkçe "kol" ile ses benzerliği taşısa da "yaka" (veya tasma) demektir; "white-collar workers -> beyaz yakalı çalışanlar" ise yapısal bir öyküntüdür.'),
  ('Bir hastane acil servisinde Türkçe bilmeyen bir mülteci hasta ile hekim arasındaki iletişimi sağlayan çevirmenin yaptığı iş çeviribilimde hangi alt alan kapsamında değerlendirilir?', 'Toplum çevirmenliği (community / public service interpreting)', ['Edebi ve sanatsal kurmaca çevirisi', 'Yazılım arayüzü yerelleştirmesi (UI localization)', 'Kabin içi çok dilli konferans çevirisi'], 'Sağlık, eğitim, göç idaresi ve mahkeme gibi kamu hizmetlerine erişimde bireylerle kurumlar arasında yapılan sözlü çeviriye toplum çevirmenliği denir.'),
  ('İngilizce "convenient" sıfatı "Is five o\'clock convenient for you?" cümlesinde kullanılırken Fransızca bilen veya Türkçe "konvansiyonel" kelimesini düşünen birinin yanılma nedeni nedir?', '"Convenient" uygun/elverişli demektir; geleneksel anlamındaki "conventional" ile karıştırılmaktadır.', ['"Convenient" resmi sözleşmeye dayalı demektir; "comfortable" ile eş anlamlı sanılmaktadır.', '"Convenient" zorunlu ve kesin demektir; "ikna edici" anlamındaki "convincing" ile aynıdır.', '"Convenient" pahalı ve gösterişli demektir; "ucuz" anlamındaki "economical" yerine kullanılmaktadır.'], '"Convenient" zahmetsiz, uygun, elverişli demektir; "geleneksel/alışılmış" anlamını taşıyan sözcük ise "conventional"dır.'),
  ('Altyazı (subtitling) çevirisini yazılı kitap çevirisinden ayıran en önemli teknik kısıtlama aşağıdakilerden hangisidir?', 'Ekranda kalma süresine ve satır başına düşen karakter sayısına bağlı uzamsal-zamansal sınır', ['Çevirmenin dipnot ve parantez içi uzun akademik açıklamalar ekleme zorunluluğu', 'Kaynak dildeki konuşma hızının iki katı uzunlukta edebi betimlemeler kullanılması', 'Yalnızca siyah-beyaz belgesel filmlerde tek satır halinde uygulanabilmesi'], 'İzleyicinin görüntüyü kaçırmadan metni okuyabilmesi için altyazıda genellikle en fazla iki satır ve belirli bir karakter/saniye sınırı uygulanır; bu nedenle metin yoğunlaştırılır.'),
  ('Bir çevirmen İngilizce bir romandaki "He was sitting in the library reading a novel about a brave chef." cümlesini "Kitapçıda oturmuş, uslu bir büro şefi hakkında yeni bir dergi okuyordu." diye çevirmiştir. Bu çeviride kaç adet yalancı eşdeğer hatası yapılmıştır?', 'Dört (library, novel, brave, chef)', ['İki (yalnızca library ve chef)', 'Üç (yalnızca library, novel ve chef)', 'Bir (yalnızca brave sıfatı)'], 'Library (kitapçı değil kütüphane), novel (dergi değil roman), brave (uslu değil cesur) ve chef (büro şefi değil aşçıbaşı) olmak üzere dört sözcük de yanlış aktarılmıştır.'),
  ('Küresel bir reklam kampanyasının sloganını başka bir ülkeye uyarlarken, kaynak metne sadık kalmak yerine markanın hedef kültürde aynı duygusal etkiyi yaratması için sloganın yaratıcı biçimde yeniden yazılmasına ne ad verilir?', 'Yaratıcı çeviri (transcreation)', ['Birebir satır arası çeviri (gloss translation)', 'Biçimsel öyküntüleme (structural calque)', 'Fonetik harf çevirisi (transliteration)'], '"Translation" ve "creation" sözcüklerinin birleşimi olan "transcreation" (yaratıcı çeviri), reklam ve pazarlama metinlerinde duygusal/ikna edici etkiyi korumak için metni yeniden kurgulamaktır.'),
  ('"The factory director made a sensible decision regarding the actual production costs of the cotton fabric." cümlesinin en doğru ve eksiksiz Türkçe çevirisi hangisidir?', 'Fabrika müdürü, pamuklu kumaşın gerçek üretim maliyetlerine ilişkin mantıklı bir karar aldı.', ['Kumaş yöneticisi, fabrika üretiminin güncel maliyetleri konusunda çok duygusal bir karar aldı.', 'Fabrika orkestra şefi, pamuk fabrikasının olası üretim giderleri hakkında hassas bir karar verdi.', 'Atölye müdürü, pamuklu dokumanın aktüel satış fiyatlarına dair geçici bir karar açıkladı.'], 'Factory=fabrika, sensible=mantıklı, actual=gerçek, fabric=kumaş karşılıklarının tamamı yalancı eşdeğer tuzağına düşülmeden ilk seçenekte doğru verilmiştir.'),
  ('Bir konferansta eşzamanlı çevirmenin konuşmacının cümle yapısını ve yüklemini anlayabilmek için konuşmacının birkaç saniye gerisinden gelerek çeviri yapması durumunu değerlendiren hangi ifade doğrudur?', '"Décalage" (kulak-dil aralığı) adı verilen bu kısa gecikme, sözdizimi farklı diller arasında doğru anlam kurmak için doğal ve gereklidir.', ['Bu gecikme çevirmenin yetersizliğini gösterir; kusursuz bir çevirmen konuşmacıyla salisesi salisesine aynı anda konuşmalıdır.', 'Gecikme süresi ne kadar uzatılırsa kısa süreli bellek yükü o kadar azalacağından en az iki dakika geriden gelinmelidir.', 'Yalnızca aynı dil ailesinden diller arasında görülür; İngilizce-Türkçe çeviride yüklem başta olduğu için gecikme sıfırdır.'], 'Türkçe gibi yüklemi sonda, İngilizce gibi yüklemi ortada olan diller arasında çeviri yaparken "décalage" (genellikle 2-5 saniye) doğru anlamlandırma ile bellek kapasitesi arasındaki stratejik dengedir.'),
];
